def semantic_fingerprint(text: str) -> str:
    """
    Грубый смысловой отпечаток:
    убираем форму, оставляем ядро.
    """
    t = text.lower()
    t = re.sub(r"[^\w\s]", "", t)
    t = re.sub(r"\s+", " ", t).strip()
    words = [w for w in t.split() if len(w) > 3]
    return " ".join(words[:20])


    
