def save_bot_state() -> None:
    """Save bot emotional/mood/goal states to bot_state.json"""
    from dataclasses import asdict
    try:
        state = {
            "bot_emotion": asdict(bot_emotion),
            "bot_mood": asdict(bot_mood),
            "bot_goal_state": asdict(bot_goal_state),
            "subjective_experience_state": asdict(subjective_experience_state),
            "bot_relationship_state": dict(bot_relationship_state),
            "user_state": {str(k): v for k, v in user_state.items()},
            "current_mode": {str(k): v for k, v in current_mode.items()},
            "user_emotion": {str(k): v for k, v in user_emotion.items()},
            "impression_state": {
                str(k): asdict(v) for k, v in impression_state.items()
            },
            "emotion_identity": {
                str(k): asdict(v) for k, v in emotion_identity.items()
            },
            "user_emotion_buffer": {
                str(k): asdict(v) for k, v in user_emotion_buffer.items()
            },
        }
        save_json(BOT_STATE_FILE, state)
    except Exception:
        logging.exception("save_bot_state failed")


def load_bot_state() -> None:
    """Restore bot emotional/mood/goal states from bot_state.json"""
    from dataclasses import dataclass
    data = load_json(BOT_STATE_FILE)
    if not data:
        return
    try:
        # bot_emotion
        e = data.get("bot_emotion")
        if e:
            bot_emotion.warmth = e.get("warmth", 0.0)
            bot_emotion.tension = e.get("tension", 0.0)
            bot_emotion.trust = e.get("trust", 0.0)
            bot_emotion.curiosity = e.get("curiosity", 0.0)
            bot_emotion.fatigue = e.get("fatigue", 0.0)
            bot_emotion.sync = e.get("sync", 0.0)
            bot_emotion.latent_warmth = e.get("latent_warmth", 0.0)
            bot_emotion.latent_tension = e.get("latent_tension", 0.0)
            bot_emotion.latent_trust = e.get("latent_trust", 0.0)
            bot_emotion.latent_curiosity = e.get("latent_curiosity", 0.0)

        # bot_mood
        m = data.get("bot_mood")
        if m:
            bot_mood.boredom = m.get("boredom", 0.0)
            bot_mood.interest = m.get("interest", 0.0)
            bot_mood.confidence = m.get("confidence", 0.5)
            bot_mood.frustration = m.get("frustration", 0.0)
            bot_mood.loneliness = m.get("loneliness", 0.0)
            bot_mood.relief = m.get("relief", 0.0)
            bot_mood.anticipation = m.get("anticipation", 0.0)

        # bot_goal_state
        g = data.get("bot_goal_state")
        if g:
            bot_goal_state.primary = g.get("primary", bot_goal_state.primary)
            bot_goal_state.secondary = g.get("secondary", bot_goal_state.secondary)
            bot_goal_state.tertiary = g.get("tertiary", bot_goal_state.tertiary)
            bot_goal_state.exploration_drive = g.get("exploration_drive", 0.55)
            bot_goal_state.social_drive = g.get("social_drive", 0.50)
            bot_goal_state.stability_drive = g.get("stability_drive", 0.65)

        # subjective_experience_state
        s = data.get("subjective_experience_state")
        if s:
            subjective_experience_state.presence = s.get("presence", 0.55)
            subjective_experience_state.vividness = s.get("vividness", 0.50)
            subjective_experience_state.self_continuity = s.get("self_continuity", 0.60)
            subjective_experience_state.felt_agency = s.get("felt_agency", 0.50)
            subjective_experience_state.inner_resonance = s.get("inner_resonance", 0.45)
            subjective_experience_state.narrative_pull = s.get("narrative_pull", 0.40)
            subjective_experience_state.uncertainty = s.get("uncertainty", 0.25)
            subjective_experience_state.temporal_depth = s.get("temporal_depth", 0.45)

        # bot_relationship_state
        r = data.get("bot_relationship_state")
        if r:
            bot_relationship_state.update(r)

        # user_state
        us = data.get("user_state", {})
        for k, v in us.items():
            user_state[int(k)] = v

        # current_mode
        cm = data.get("current_mode", {})
        for k, v in cm.items():
            current_mode[int(k)] = v

        # user_emotion
        ue = data.get("user_emotion", {})
        for k, v in ue.items():
            user_emotion[int(k)] = v

        # impression_state
        imp = data.get("impression_state", {})
        for k, v in imp.items():
            impression_state[int(k)] = ImpressionState(**v)

        # emotion_identity
        ei = data.get("emotion_identity", {})
        for k, v in ei.items():
            emotion_identity[int(k)] = EmotionIdentityCore(**v)

        # user_emotion_buffer
        ueb = data.get("user_emotion_buffer", {})
        for k, v in ueb.items():
            user_emotion_buffer[int(k)] = EmotionState(**v)

    except Exception:
        logging.exception("load_bot_state failed")


# ---------- ИМЕНА: Telegram = источник истины ----------

def _clean_display_name(raw: str) -> str:
    """Убирает декоративные артефакты вида '| | EVA // Ω' → 'EVA'."""
    s = (raw or "").strip()
    s = re.sub(r"^[\s|•·.\-/]+", "", s)
    s = re.split(r"\s*(?://|\|\|)\s*", s, maxsplit=1)[0].strip()
    s = re.sub(r"[\s|•·]+$", "", s)
    return s.strip(" .,;:")


def _user_full_name(profile: dict) -> str:
    """Имя + фамилия из Telegram (очищенные). Пусто, если Telegram-имени нет."""
    tg = profile.get("telegram_identity", {}) or {}
    first = _clean_display_name(tg.get("first_name") or "")
    if not first:
        return ""
    last_raw = (tg.get("last_name") or "").strip()
    last = ""
    if last_raw:
        tok = last_raw.split()[0].strip(" .,;:")
        is_word = bool(re.fullmatch(r"\w+", tok)) and any(c.isalpha() for c in tok)
        long_enough = len(tok) >= 2 or (tok and ord(tok[0]) > 127)
        if is_word and long_enough and tok.lower() != first.lower():
            last = tok
    return (first + (" " + last if last else "")).strip()


# ---------- USER IDENTITY MANAGER ----------
# Единая точка доступа к идентичности пользователя.
# Все остальные подсистемы читают идентичность ТОЛЬКО через этот менеджер.

class UserIdentityManager:
    """
    Управляет идентичностью пользователя:
    - Telegram identity (всегда свежий)
    - Preferred name, gender, dreams, projects с importance scores
    - Извлечение фактов после каждого обмена
    - Восстановление профиля из long_memory
    """

    def sync_telegram_identity(self, tg_user, profile: dict) -> bool:
        """
        Синхронизирует Telegram-данные в профиль.
        Вызывается на КАЖДОМ сообщении. Telegram = источник истины для identity.
        """
        if tg_user is None:
            return False

        changed = False
        ident = profile.get("telegram_identity")
        if not isinstance(ident, dict):
            ident = {}
            profile["telegram_identity"] = ident

        tid = getattr(tg_user, "id", None)
        if tid and ident.get("telegram_id") != tid:
            ident["telegram_id"] = tid
            changed = True

        for field in ("username", "first_name", "last_name", "language_code", "is_premium"):
            val = getattr(tg_user, field, None)
            if val is not None and ident.get(field) != val:
                ident[field] = val
                changed = True

        photo = getattr(tg_user, "photo", None)
        if photo:
            fid = getattr(photo, "file_id", None)
            if fid and ident.get("photo_file_id") != fid:
                ident["photo_file_id"] = fid
                changed = True

        ident["updated_at"] = datetime.now().isoformat()

        # preferred_name всегда = имя+фамилия из Telegram (очищенные).
        # Пересчитывается на каждом сообщении, чтобы юзер видел актуальное имя.
        self._ensure_structured_fields(profile)
        return changed

    # Names that extract_name_from_text can produce by mistake
    _GARBAGE_NAMES = {
        "зовут", "называюсь", "можешь", "звать", "зови", "меня",
        "имя", "это", "я", "нет", "да", "ок", "привет", "пока",
        "найди", "поищи", "расскажи", "объясни", "помоги",
        "хочу", "могу", "буду", "думаю", "знаю", "мечта",
        "ты", "тебя", "тебе", "тобой", "вы", "вас", "он", "она",
        "они", "мы", "нас", "себя", "себе", "собой", "мой", "твой",
        "своё", "своя", "свою", "другой", "сам", "сама", "сама",
    }

    def _ensure_structured_fields(self, profile: dict) -> None:
        """Мигрирует старые плоские поля в новую структуру."""
        if "identity" not in profile:
            profile["identity"] = {}
        ident = profile["identity"]

        # Determine preferred_name with validation
        candidate = (
            profile.get("preferred_name")
            or profile.get("name")
            or ""
        ).strip()

        # Reject garbage names from parser — fall through to Telegram
        if candidate.lower() in self._GARBAGE_NAMES or len(candidate) < 2:
            candidate = ""

        # Telegram = источник истины для имени: имя+фамилия из TG приоритетнее
        tg_full = _user_full_name(profile)
        tg_first = (profile.get("telegram_identity", {}).get("first_name") or "").strip()
        if tg_full:
            candidate = tg_full
        elif not candidate and tg_first:
            candidate = _clean_display_name(tg_first)

        ident["preferred_name"] = candidate or "неизвестно"
        ident["pronouns"] = profile.get("pronouns", "не указаны")
        ident["gender_identity"] = profile.get("gender", "не указан")
        ident["grammatical_gender"] = profile.get("grammatical_gender", "не указан")

        # Migrate old flat name if present
        old_name = profile.get("name")
        if old_name and not ident.get("preferred_name"):
            ident["preferred_name"] = old_name

        # preferences
        if "preferences" not in profile:
            profile["preferences"] = {}
        prefs = profile["preferences"]
        if "emoji" not in prefs:
            prefs["emoji"] = True
        if "voice" not in prefs:
            prefs["voice"] = False
        if "short_answers" not in prefs:
            prefs["short_answers"] = False

        # dreams — миграция из строки в список с importance
        if "dreams" not in profile:
            old_dream = profile.get("dream")
            if old_dream:
                profile["dreams"] = [{
                    "text": old_dream,
                    "importance": 0.8,
                    "mentions": 1,
                    "last_seen": datetime.now().isoformat(),
                    "confidence": 0.7,
                }]
            else:
                profile["dreams"] = []

        # projects
        if "projects" not in profile:
            profile["projects"] = []

        # relationships
        if "relationships" not in profile:
            profile["relationships"] = []

        # goals → projects migration
        old_goals = profile.get("goals")
        if isinstance(old_goals, list) and old_goals and not profile["projects"]:
            for g in old_goals[:5]:
                if isinstance(g, dict) and g.get("text"):
                    profile["projects"].append({
                        "text": g["text"],
                        "importance": 0.6,
                        "mentions": 1,
                        "last_seen": g.get("created", datetime.now().isoformat()),
                    })

    def get_identity_context(self, uid: int) -> str:
        """
        Возвращает человекочитаемый текст профиля для промпта.
        Имя пользователя — ПЕРВАЯ строка, чтобы модель точно его заметила.
        """
        profile = get_user_profile(uid)
        self._ensure_structured_fields(profile)

        ident = profile.get("identity", {})
        telegram = profile.get("telegram_identity", {})
        prefs = profile.get("preferences", {})
        dreams = profile.get("dreams", [])
        projects = profile.get("projects", [])
        city = profile.get("city", "не указан")

        name = ident.get("preferred_name", "неизвестно")
        username = telegram.get("username", "")
        tg_first = telegram.get("first_name", "")
        gender = ident.get("gender_identity", "не указан")
        pronouns = ident.get("pronouns", "не указаны")
        lang = telegram.get("language_code", "ru")

        parts = []
        # NAME FIRST — модель должна видеть имя сразу
        parts.append(f"USER PROFILE:")
        if username:
            parts.append(f"username: @{username}")
        tg_clean = _clean_display_name(tg_first)
        if tg_clean and tg_clean != name:
            parts.append(f"telegram name: {tg_clean}")
        parts.append(f"name: {name}")
        parts.append(f"gender: {gender}")
        parts.append(f"pronouns: {pronouns}")
        parts.append(f"language: {lang}")
        parts.append(f"city: {city}")

        if dreams:
            parts.append("")
            parts.append("DREAMS:")
            for d in dreams[:5]:
                if isinstance(d, dict) and d.get("text"):
                    parts.append(f"- {d['text']}")

        if projects:
            parts.append("")
            parts.append("PROJECTS:")
            for p in projects[:5]:
                if isinstance(p, dict) and p.get("text"):
                    parts.append(f"- {p['text']}")

        return "\n".join(parts)

    def extract_profile_delta(self, uid: int, user_text: str, assistant_text: str) -> None:
        """
        После КАЖДОГО ответа модели извлекает новые факты о пользователе
        и обновляет профиль. Лёгкая эвристика — не требует LLM-вызова.
        """
        profile = get_user_profile(uid)
        self._ensure_structured_fields(profile)
        changed = False

        t = (user_text or "").lower().strip()
        if not t:
            return

        # --- Name: берём только из Telegram (см. _ensure_structured_fields) ---
        ident = profile.get("identity", {})

        # --- Dreams ---
        dreams = profile.get("dreams", [])
        dream_keywords = ["мечта", "хочу", "мечтаю", "стремлюсь", "хотел бы", "моя цель"]
        for kw in dream_keywords:
            if kw in t:
                dream_text = user_text.strip()
                # Проверяем, не дублирует ли
                existing = False
                for d in dreams:
                    if isinstance(d, dict) and self._texts_similar(d.get("text", ""), dream_text):
                        d["mentions"] = d.get("mentions", 1) + 1
                        d["confidence"] = min(1.0, d.get("confidence", 0.5) + 0.1)
                        d["last_seen"] = datetime.now().isoformat()
                        existing = True
                        changed = True
                        break
                if not existing and len(dreams) < 10:
                    dreams.append({
                        "text": dream_text,
                        "importance": 0.7,
                        "mentions": 1,
                        "last_seen": datetime.now().isoformat(),
                        "confidence": 0.6,
                    })
                    changed = True
                break

        # --- Fears ---
        fear_keywords = ["боюсь", "страх", "тревога", "беспокоит"]
        for kw in fear_keywords:
            if kw in t:
                old_fears = profile.get("fears", "")
                if not old_fears:
                    profile["fears"] = user_text.strip()
                    changed = True
                break

        # --- Values ---
        value_keywords = ["ценю", "важно для меня", "главное", "приоритет"]
        for kw in value_keywords:
            if kw in t:
                old_vals = profile.get("values", "")
                if not old_vals:
                    profile["values"] = user_text.strip()
                    changed = True
                break

        # --- Projects (если пользователь говорит о работе/проекте) ---
        projects = profile.get("projects", [])
        project_keywords = ["проект", "работаю над", "делаю", "пишу код", "разрабатываю"]
        for kw in project_keywords:
            if kw in t:
                proj_text = user_text.strip()
                existing = False
                for p in projects:
                    if isinstance(p, dict) and self._texts_similar(p.get("text", ""), proj_text):
                        p["mentions"] = p.get("mentions", 1) + 1
                        p["last_seen"] = datetime.now().isoformat()
                        existing = True
                        changed = True
                        break
                if not existing and len(projects) < 10:
                    projects.append({
                        "text": proj_text,
                        "importance": 0.6,
                        "mentions": 1,
                        "last_seen": datetime.now().isoformat(),
                    })
                    changed = True
                break

        # --- Gender (из ответа пользователя на вопрос о гендере) ---
        ident = profile.get("identity", {})
        if ident.get("gender_identity", "не указан") == "не указан":
            gender = infer_gender_from_text(user_text)
            if gender != "не указан":
                ident["gender_identity"] = gender
                profile["gender"] = gender
                changed = True

        # --- Pronouns (автоиз русского текста) ---
        if ident.get("pronouns", "не указаны") == "не указаны":
            if any(w in t for w in ["я девушка", "я женщина", "я девочка"]):
                ident["pronouns"] = "she/her"
                ident["grammatical_gender"] = "feminine"
                changed = True
            elif any(w in t for w in ["я парень", "я мужчина", "я мальчик"]):
                ident["pronouns"] = "he/him"
                ident["grammatical_gender"] = "masculine"
                changed = True

        # --- Reinforcement: повторное упоминание имени ---
        pref_name = ident.get("preferred_name", "")
        if pref_name and pref_name.lower() in t:
            # Пользователь подтвердил имя
            profile["name_confirmed"] = profile.get("name_confirmed", 0) + 1
            changed = True

        if changed:
            save_user_profile(uid)

    def rebuild_profile_from_long_memory(self, uid: int) -> bool:
        """
        Если профиль пуст/повреждён — восстанавливает из long_memory (SQLite).
        """
        profile = get_user_profile(uid)
        has_data = any([
            profile.get("name"),
            profile.get("preferred_name"),
            profile.get("gender") and profile.get("gender") != "не указан",
            profile.get("dream"),
            profile.get("dreams"),
        ])
        if has_data:
            return False

        # Scan long_memory for facts
        try:
            rows = get_long_memory(uid, limit=200)
        except Exception:
            return False

        if not rows:
            return False

        names_found = []
        for row in rows:
            content = (row.get("content") or "").lower()
            if "меня зовут" in content or "моё имя" in content or "мое имя" in content:
                for phrase in ["меня зовут", "моё имя", "мое имя"]:
                    if phrase in content:
                        name_part = content.split(phrase, 1)[-1].strip().split()[0:2]
                        if name_part:
                            names_found.append(" ".join(name_part).strip(".,!"))
            if "мечта" in content or "хочу" in content:
                if not profile.get("dream") and not profile.get("dreams"):
                    profile["dream"] = row.get("content", "")[:200]

        if names_found:
            from collections import Counter
            most_common = Counter(names_found).most_common(1)[0][0]
            profile["preferred_name"] = most_common
            profile["name"] = most_common

        self._ensure_structured_fields(profile)
        save_user_profile(uid)
        return True

    @staticmethod
    def _texts_similar(a: str, b: str, threshold: float = 0.6) -> bool:
        """Грубое сравнение текстов для dedup."""
        a = (a or "").lower().strip()[:100]
        b = (b or "").lower().strip()[:100]
        if not a or not b:
            return False
        if a == b:
            return True
        # Jaccard on words
        wa = set(a.split())
        wb = set(b.split())
        if not wa or not wb:
            return False
        overlap = len(wa & wb) / max(1, len(wa | wb))
        return overlap >= threshold


identity_manager = UserIdentityManager()


def _now_iso_goal() -> str:
    return datetime.now().isoformat()


def _ensure_goal_store(profile: dict) -> list[dict]:
    goals = profile.get("goals")
    if not isinstance(goals, list):
        goals = []
    profile["goals"] = goals
    return goals


def add_user_goal(user_id: int, text: str, due_iso: str | None = None) -> dict | None:
    t = (text or "").strip()
    if not t:
        return None
    profile = get_user_profile(user_id)
    goals = _ensure_goal_store(profile)
    gid = f"g{int(time.time())}{random.randint(100,999)}"
    item = {
        "id": gid,
        "text": t[:500],
        "status": "open",
        "created": _now_iso_goal(),
        "updated": _now_iso_goal(),
        "due": (due_iso or "").strip() or None,
    }
    goals.append(item)
    profile["goals"] = goals[-50:]
    save_user_profile(user_id)
    return item


def list_user_goals(user_id: int, only_open: bool = True) -> list[dict]:
    profile = get_user_profile(user_id)
    goals = profile.get("goals")
    if not isinstance(goals, list):
        return []
    out = []
    for g in goals:
        if not isinstance(g, dict):
            continue
        if only_open and (g.get("status") != "open"):
            continue
        out.append(g)
    return out


def complete_user_goal(user_id: int, goal_id: str) -> bool:
    profile = get_user_profile(user_id)
    goals = profile.get("goals")
    if not isinstance(goals, list):
        return False
    gid = (goal_id or "").strip()
    if not gid:
        return False
    ok = False
    for g in goals:
        if not isinstance(g, dict):
            continue
        if (g.get("id") or "") == gid:
            g["status"] = "done"
            g["updated"] = _now_iso_goal()
            ok = True
            break
    if ok:
        profile["goals"] = goals
        save_user_profile(user_id)
    return ok


def goals_context_for_prompt(user_id: int, limit: int = 3) -> str:
    goals = list_user_goals(user_id, only_open=True)
    if not goals:
        return ""
    # Prefer due goals first
    def _key(g: dict):
        due = g.get("due") or ""
        return (0 if due else 1, due, g.get("created") or "")
    goals.sort(key=_key)
    lines = ["[ACTIVE_GOALS]"]
    for g in goals[:limit]:
        due = g.get("due") or "-"
        lines.append(f"- {g.get('id')}: {g.get('text','')[:220]} (due: {due})")
    lines.append("Prefer helping with these goals when relevant. Do not add headers like 'Следующий шаг:'.")
    return "\n".join(lines)


def build_internal_intention_state(
    user_id: int,
    user_text: str = "",
    emotion_state: Any | None = None,
    swarm_feedback: dict | None = None,
) -> dict:
    """
    Lightweight internal intentionality sidecar.
    Keeps goals/values/uncertainty together without entering the main user reply loop.
    """
    profile = get_user_profile(user_id)
    goals = list_user_goals(user_id, only_open=True)
    values_text = (profile.get("values") or "").strip()
    reasoning = get_user_reasoning(user_id)
    meaning = get_user_meaning(user_id)

    if swarm_feedback is None:
        swarm_feedback = {}

    tension = float(getattr(emotion_state, "tension", 0.0) or 0.0) if emotion_state else 0.0
    trust = float(getattr(emotion_state, "trust", 0.0) or 0.0) if emotion_state else 0.0
    curiosity = float(getattr(emotion_state, "curiosity", 0.0) or 0.0) if emotion_state else 0.0
    planning = float(reasoning.get("planning", 0.0) or 0.0)
    goal_text = (goals[0].get("text") or "").strip() if goals else ""

    ambiguity = 0.0
    if user_text and re.search(r"(?i)\b(может|не знаю|не уверен|не уверена|что если|maybe|not sure)\b", user_text):
        ambiguity = 0.18

    uncertainty = clamp(
        0.42 * max(0.0, tension) +
        0.24 * max(0.0, 1.0 - max(0.0, trust)) +
        0.14 * ambiguity +
        0.10 * max(0.0, -float(swarm_feedback.get("stability", 0.0) or 0.0)) +
        0.10 * (0.0 if goal_text else 0.25),
        0.0,
        1.0
    )

    if goal_text:
        primary = f"support_goal:{goal_text[:160]}"
        self_query = "Какой следующий шаг действительно продвинет текущую цель?"
    elif values_text:
        primary = f"protect_values:{values_text[:120]}"
        self_query = "Как сохранить полезность, не отходя от ценностей пользователя?"
    elif meaning.get("goals", 0) > 0 or planning > 0.8:
        primary = "turn_reflection_into_action"
        self_query = "Как превратить разговор в конкретный следующий шаг?"
    elif curiosity > 0.35:
        primary = "explore_new_pattern"
        self_query = "Что стоит исследовать глубже, чтобы появился новый паттерн?"
    else:
        primary = "stay_useful_and_coherent"
        self_query = "Что здесь сейчас важнее всего для пользы и ясности?"

    if uncertainty > 0.62:
        action_mode = "clarify"
    elif goal_text and planning > 0.8:
        action_mode = "plan"
    elif tension > 0.45:
        action_mode = "stabilize"
    else:
        action_mode = "advance"

    return {
        "primary": primary,
        "goal": goal_text[:220],
        "values": values_text[:220],
        "self_query": self_query,
        "action_mode": action_mode,
        "uncertainty": round(float(uncertainty), 3),
        "planning": round(planning, 3),
        "curiosity": round(curiosity, 3),
        "ts": datetime.now().isoformat(),
    }


def update_internal_intention_state(
    user_id: int,
    user_text: str = "",
    emotion_state: Any | None = None,
    swarm_feedback: dict | None = None,
) -> dict:
    """
    Persist compact intentionality state for internal routines and steering only.
    """
    profile = get_user_profile(user_id)
    state = build_internal_intention_state(
        user_id,
        user_text=user_text,
        emotion_state=emotion_state,
        swarm_feedback=swarm_feedback,
    )
    profile["internal_intention_state"] = state
    save_user_profile(user_id)
    return state


def get_internal_intention_state(user_id: int) -> dict:
    profile = get_user_profile(user_id)
    state = profile.get("internal_intention_state")
    if isinstance(state, dict):
        return state
    return {}


def set_swarm_focus_for_user(user_id: int) -> None:
    """
    Internal-only: steer swarm agents toward user's active goals.
    Must never be shown verbatim to the user.
    """
    goals = list_user_goals(user_id, only_open=True)
    state = get_internal_intention_state(user_id)
    goal_text = ""
    if goals:
        goal_text = (goals[0].get("text") or "").strip()
    if goal_text:
        focus = f"помочь пользователю {user_id} с целью: {goal_text[:180]}"
    elif state.get("values"):
        focus = f"удерживать ценностную линию пользователя {user_id}: {(state.get('values') or '')[:160]}"
    else:
        focus = f"дать пользователю {user_id} более ясное и целенаправленное продолжение диалога"

    if state.get("action_mode"):
        focus += f" | mode={state['action_mode']}"
    if state.get("self_query"):
        focus += f" | query={(state['self_query'] or '')[:120]}"
    try:
        for a in getattr(swarm, "agents", []):
            if getattr(a, "is_alive", False):
                a.current_goal = focus
    except Exception:
        pass


@dataclass
class InternalVectorState:
    text: str = ""
    embedding: np.ndarray = field(default_factory=lambda: np.zeros(768, dtype=float))

    def get(self) -> np.ndarray:
        return np.asarray(self.embedding, dtype=float).reshape(-1)

    def update(self, new_embedding: np.ndarray | None = None, new_text: str | None = None, mix: float = 0.9) -> np.ndarray:
        mix = float(np.clip(mix, 0.0, 1.0))
        if new_text is not None:
            self.text = (new_text or "").strip()[:400]
        if new_embedding is None:
            return self.get()

        current = self.get()
        incoming = np.asarray(new_embedding, dtype=float).reshape(-1)
        if current.shape[0] != incoming.shape[0]:
            size = min(current.shape[0], incoming.shape[0])
            current = current[:size]
            incoming = incoming[:size]

        merged = mix * current + (1.0 - mix) * incoming
        norm = np.linalg.norm(merged)
        if norm > 1e-8:
            merged = merged / norm
        self.embedding = merged
        return self.get()


class AgentLoop:
    def __init__(self, trigger_threshold: float = 0.75, max_steps: int = 3, cooldown_steps: int = 2):
        self.last_action_strength = 0.0
        self.last_trigger_score = 0.0
        self.cooldown = 0
        self.trigger_threshold = float(trigger_threshold)
        self.max_steps = int(max_steps)
        self.cooldown_steps = int(cooldown_steps)

    def should_trigger(self, query_emb, self_state, goal_state, uncertainty: float = 0.0, force_trigger: bool = False):
        if self.cooldown > 0:
            self.cooldown -= 1
            return False

        query_emb = np.asarray(query_emb, dtype=float).reshape(-1)
        self_state = np.asarray(self_state, dtype=float).reshape(-1)
        goal_state = np.asarray(goal_state, dtype=float).reshape(-1)

        alignment = _cosine(query_emb, goal_state)
        inertia = _cosine(self_state, goal_state)
        trigger_score = 0.6 * alignment + 0.4 * inertia

        if uncertainty > 0.7:
            trigger_score = max(trigger_score, 0.76)
        if force_trigger:
            trigger_score = max(trigger_score, self.trigger_threshold + 0.02)

        self.last_trigger_score = float(trigger_score)
        return trigger_score > self.trigger_threshold

    def decide_action(self, meta_output: dict) -> str:
        uncertainty = float(meta_output.get("uncertainty", 0.0) or 0.0)
        goal_alignment = float(meta_output.get("goal_alignment", 0.0) or 0.0)
        action_mode = (meta_output.get("action_mode") or "").strip().lower()

        if uncertainty > 0.7:
            return "think"
        if action_mode == "plan":
            return "plan"
        if action_mode == "stabilize":
            return "reflect"
        if action_mode == "clarify":
            return "search" if goal_alignment < 0.45 else "refine"
        if goal_alignment > 0.82:
            return "write"
        return "refine"

    def execute(self, action: str, z: np.ndarray, self_state: np.ndarray, goal_state: np.ndarray) -> dict:
        z = np.asarray(z, dtype=float).reshape(-1)
        self_state = np.asarray(self_state, dtype=float).reshape(-1)
        goal_state = np.asarray(goal_state, dtype=float).reshape(-1)

        if action == "think":
            combined = 0.55 * z + 0.30 * self_state + 0.15 * goal_state
            strength = 0.35
        elif action == "write":
            combined = 0.45 * z + 0.20 * self_state + 0.35 * goal_state
            strength = 0.75
        elif action == "search":
            combined = 0.50 * z + 0.10 * self_state + 0.40 * goal_state
            strength = 0.55
        elif action == "plan":
            combined = 0.40 * z + 0.25 * self_state + 0.35 * goal_state
            strength = 0.65
        elif action == "reflect":
            combined = 0.35 * z + 0.45 * self_state + 0.20 * goal_state
            strength = 0.45
        else:
            combined = 0.50 * z + 0.25 * self_state + 0.25 * goal_state
            strength = 0.50

        norm = np.linalg.norm(combined)
        if norm > 1e-8:
            combined = combined / norm

        next_self = 0.90 * self_state + 0.10 * combined
        next_goal = 0.97 * goal_state + 0.03 * combined
        next_query = 0.85 * z + 0.15 * combined

        next_self_norm = np.linalg.norm(next_self)
        if next_self_norm > 1e-8:
            next_self = next_self / next_self_norm
        next_goal_norm = np.linalg.norm(next_goal)
        if next_goal_norm > 1e-8:
            next_goal = next_goal / next_goal_norm
        next_query_norm = np.linalg.norm(next_query)
        if next_query_norm > 1e-8:
            next_query = next_query / next_query_norm

        self.last_action_strength = float(strength)
        self.cooldown = self.cooldown_steps
        return {
            "action": action,
            "result": combined,
            "self_state": next_self,
            "goal_state": next_goal,
            "query_state": next_query,
            "action_strength": float(strength),
        }


_agent_loops: dict[int, AgentLoop] = {}


def _get_agent_loop(user_id: int) -> AgentLoop:
    uid = int(user_id)
    loop = _agent_loops.get(uid)
    if loop is None:
        loop = AgentLoop()
        _agent_loops[uid] = loop
    return loop


def _coerce_internal_embedding(value: Any, fallback_text: str = "", dim: int = 768) -> np.ndarray:
    if isinstance(value, np.ndarray):
        arr = np.asarray(value, dtype=float).reshape(-1)
    elif isinstance(value, (list, tuple)):
        arr = np.asarray(value, dtype=float).reshape(-1)
    else:
        arr = _encode_text(fallback_text, dim=dim)

    if arr.shape[0] < dim:
        arr = np.pad(arr, (0, dim - arr.shape[0]), mode="constant")
    elif arr.shape[0] > dim:
        arr = arr[:dim]

    norm = np.linalg.norm(arr)
    if norm > 1e-8:
        arr = arr / norm
    return arr


def _load_internal_vector_state(profile: dict, key: str, fallback_text: str = "") -> InternalVectorState:
    payload = profile.get(key)
    if not isinstance(payload, dict):
        payload = {}
    text = (payload.get("text") or fallback_text or "").strip()[:400]
    emb = _coerce_internal_embedding(payload.get("embedding"), fallback_text=text)
    return InternalVectorState(text=text, embedding=emb)


def _save_internal_vector_state(profile: dict, key: str, state: InternalVectorState) -> None:
    profile[key] = {
        "text": (state.text or "")[:400],
        "embedding": state.get().tolist(),
        "updated_at": datetime.now().isoformat(),
    }


def run_self_trigger_cycle(
    user_id: int,
    input_text: str = "",
    intention_state: dict | None = None,
    max_self_steps: int = 3,
) -> dict:
    profile = get_user_profile(int(user_id))
    intention_state = intention_state or {}
    loop = _get_agent_loop(user_id)

    goal_text = (intention_state.get("goal") or intention_state.get("primary") or "").strip()
    self_query_text = (intention_state.get("self_query") or input_text or goal_text or "").strip()
    if not self_query_text:
        self_query_text = "reflect"

    self_state = _load_internal_vector_state(profile, "self_trigger_self_state", fallback_text=self_query_text)
    goal_state = _load_internal_vector_state(profile, "self_trigger_goal_state", fallback_text=goal_text or self_query_text)

    query_text = (input_text or "").strip() or self_state.text or self_query_text
    query_emb = _encode_text(query_text)
    self_emb = self_state.get()
    goal_emb = goal_state.get()

    uncertainty = float(intention_state.get("uncertainty", 0.0) or 0.0)
    action_mode = (intention_state.get("action_mode") or "").strip().lower()
    force_trigger = uncertainty > 0.7
    max_steps = max(1, min(int(max_self_steps), 3))

    steps = []
    triggered = False
    last_action = "refine"

    for _ in range(max_steps):
        if not loop.should_trigger(query_emb, self_emb, goal_emb, uncertainty=uncertainty, force_trigger=force_trigger):
            break

        # === SEGMENT-LEVEL LOCAL ATTENTION для self-состояния ===
        # Локальное (оконное) внимание над текстом self-состояния: уточняем
        # внутренний вектор, удерживая локальные связи между его частями.
        try:
            self_text = (self_state.text or query_text or "").strip()
            self_segments = local_windowed_attention.segment_text(self_text)
            local_out = local_windowed_attention.forward(self_segments, query_vec=query_emb)
            refined_self = local_out["embedding"] if local_out["n_segments"] else self_emb
            local_entropy = float(local_out["local_entropy"])
            n_segments = int(local_out["n_segments"])
        except Exception:
            refined_self = self_emb
            local_entropy = 0.0
            n_segments = 0

        z = bottleneck_attention.apply(query_emb, refined_self, alpha=0.55)
        meta = meta_layer.analyze(z, refined_self)
        meta["local_entropy"] = local_entropy
        meta["n_segments"] = n_segments
        meta["goal_alignment"] = float(_cosine(z, goal_emb))
        meta["action_mode"] = action_mode
        action = loop.decide_action(meta)
        step = loop.execute(action, z, self_emb, goal_emb)

        triggered = True
        last_action = action
        self_emb = step["self_state"]
        goal_emb = step["goal_state"]
        query_emb = step["query_state"]

        steps.append({
            "action": action,
            "goal_alignment": round(float(meta["goal_alignment"]), 3),
            "uncertainty": round(float(meta.get("uncertainty", 0.0) or 0.0), 3),
            "strength": round(float(step["action_strength"]), 3),
        })

    self_state.update(self_emb, new_text=query_text, mix=0.9)
    goal_state.update(goal_emb, new_text=goal_state.text or goal_text or self_query_text, mix=0.97)

    _save_internal_vector_state(profile, "self_trigger_self_state", self_state)
    _save_internal_vector_state(profile, "self_trigger_goal_state", goal_state)
    profile["self_trigger_cycle_state"] = {
        "triggered": triggered,
        "last_action": last_action,
        "last_trigger_score": round(float(loop.last_trigger_score), 3),
        "last_action_strength": round(float(loop.last_action_strength), 3),
        "cooldown": int(loop.cooldown),
        "steps": steps[-3:],
        "updated_at": datetime.now().isoformat(),
    }
    save_user_profile(int(user_id))

    return {
        "triggered": triggered,
        "action": last_action,
        "steps": steps,
        "cooldown": int(loop.cooldown),
        "last_trigger_score": float(loop.last_trigger_score),
        "last_action_strength": float(loop.last_action_strength),
    }


