def _extract_revised_content(raw_answer: str, ext: str) -> str:
    txt = (raw_answer or "").strip()
    if not txt:
        return ""
    # Prefer largest fenced block if model wrapped output.
    blocks = re.findall(r"```(?:[a-zA-Z0-9_+-]+)?\n([\s\S]*?)```", txt)
    if blocks:
        blocks = [b.strip() for b in blocks if b and b.strip()]
        if blocks:
            return max(blocks, key=len).strip()
    return txt


def _looks_like_nonempty_revision(revised: str, original: str) -> bool:
    r = (revised or "").strip()
    o = (original or "").strip()
    if not r:
        return False
    # too short for code/text file answer -> likely broken output
    if len(r) < 20 and len(o) > 200:
        return False
    return True


async def _generate_improved_file_content(uid: int, user_text: str) -> tuple[str, str] | None:
    last_file_ctx = get_last_file_context(uid)
    if not last_file_ctx:
        return None

    filename = last_file_ctx.get("filename", "uploaded_file.txt")
    ext = last_file_ctx.get("ext", ".txt")
    file_content = (last_file_ctx.get("content") or "")[:120000]
    user_req = (last_file_ctx.get("user_request") or "").strip()
    if not file_content.strip():
        return None

    messages = get_conversation_messages(uid, limit=20)
    messages.append({
        "role": "system",
        "content": (
            "User asked to improve previously uploaded file.\n"
            "Return full improved file content first, then a short changelog."
        )
    })
    response = await query_ollama_harmony(
        messages,
        reasoning_effort="high",
        max_tokens=12000,
        temperature=0.2,
        text=(
            f"Previous file: {filename}\n"
            f"Original user request: {user_req}\n"
            f"New request: {user_text}\n\n"
            "Return ONLY revised file content. No explanation, no markdown fences.\n\n"
            f"File content:\n{file_content}"
        ),
        user_id=uid,
        inferred_intent="fact",
        force_max_tokens=12000
    )
    answer = _extract_revised_content(response.get("content") or "", ext)
    if not _looks_like_nonempty_revision(answer, file_content):
        # second try with stricter instruction
        response2 = await query_ollama_harmony(
            messages,
            reasoning_effort="high",
            max_tokens=12000,
            temperature=0.1,
            text=(
                f"File: {filename}\n"
                "Output must be the full revised file text only.\n"
                "Do not output empty response. Do not output markdown.\n\n"
                f"Source:\n{file_content}"
            ),
            user_id=uid,
            inferred_intent="fact",
            force_max_tokens=12000
        )
        answer = _extract_revised_content(response2.get("content") or "", ext)
    if not _looks_like_nonempty_revision(answer, file_content):
        # hard fallback: never send empty file
        answer = file_content
    out_name = f"{Path(filename).stem}_improved{'.js' if ext == '.jss' else ext}"
    return answer, out_name


def _safe_audio_probe(file_path: str) -> dict:
    try:
        proc = subprocess.run(
            [
                "ffprobe", "-v", "error",
                "-show_entries", "stream=sample_rate,channels,bit_rate:format=duration,bit_rate:format_tags",
                "-of", "json",
                file_path
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        if proc.returncode != 0 or not proc.stdout.strip():
            return {}
        data = json.loads(proc.stdout)
        streams = data.get("streams", []) if isinstance(data, dict) else []
        fmt = data.get("format", {}) if isinstance(data, dict) else {}
        stream0 = streams[0] if streams else {}
        tags = fmt.get("tags", {}) if isinstance(fmt, dict) else {}
        return {
            "duration_sec": float((fmt.get("duration") or 0) or 0),
            "sample_rate": int((stream0.get("sample_rate") or 0) or 0),
            "channels": int((stream0.get("channels") or 0) or 0),
            "bitrate": int((fmt.get("bit_rate") or stream0.get("bit_rate") or 0) or 0),
            "tags": tags if isinstance(tags, dict) else {},
        }
    except Exception:
        return {}


def _estimate_tempo(x: np.ndarray, sr: int) -> float:
    if x.size < sr:
        return 0.0
    frame = 1024
    hop = 256
    n = max(1, (len(x) - frame) // hop)
    env = np.empty(n, dtype=np.float32)
    prev = 0.0
    for i in range(n):
        s = i * hop
        w = x[s:s + frame]
        e = float(np.sum(np.abs(w)))
        env[i] = max(0.0, e - prev)
        prev = e
    env = env - float(np.mean(env))
    if np.allclose(env, 0.0):
        return 0.0
    ac = np.correlate(env, env, mode="full")[len(env) - 1:]
    min_bpm, max_bpm = 60.0, 190.0
    min_lag = int((60.0 / max_bpm) * (sr / hop))
    max_lag = int((60.0 / min_bpm) * (sr / hop))
    if max_lag <= min_lag or max_lag >= len(ac):
        return 0.0
    seg = ac[min_lag:max_lag]
    idx = int(np.argmax(seg))
    lag = min_lag + idx
    if lag <= 0:
        return 0.0
    return float(60.0 * (sr / hop) / lag)


def _spectral_features(x: np.ndarray, sr: int) -> dict:
    if x.size < 4096:
        return {}
    n_fft = 2048
    hop = 512
    window = np.hanning(n_fft).astype(np.float32)
    centroids = []
    rolloffs = []
    low_ratios = []
    zcrs = []
    freqs = np.fft.rfftfreq(n_fft, d=1.0 / sr)
    low_mask = freqs <= 200.0
    for s in range(0, len(x) - n_fft, hop):
        frame = x[s:s + n_fft] * window
        spec = np.abs(np.fft.rfft(frame))
        total = float(np.sum(spec)) + 1e-8
        centroids.append(float(np.sum(freqs * spec) / total))
        csum = np.cumsum(spec)
        thr = 0.85 * csum[-1]
        ridx = int(np.searchsorted(csum, thr))
        rolloffs.append(float(freqs[min(ridx, len(freqs) - 1)]))
        low_ratios.append(float(np.sum(spec[low_mask]) / total))
        signs = np.sign(frame)
        zcrs.append(float(np.mean(np.abs(np.diff(signs))) * 0.5))
    return {
        "centroid_hz": float(np.mean(centroids) if centroids else 0.0),
        "rolloff_hz": float(np.mean(rolloffs) if rolloffs else 0.0),
        "low_ratio": float(np.mean(low_ratios) if low_ratios else 0.0),
        "zcr": float(np.mean(zcrs) if zcrs else 0.0),
    }


def _spectrogram_signature(x: np.ndarray, sr: int) -> dict:
    if x.size < 4096:
        return {"spec_hash": "", "spec_profile": {}}
    n_fft = 1024
    hop = 256
    window = np.hanning(n_fft).astype(np.float32)
    frames = []
    for s in range(0, len(x) - n_fft, hop):
        frame = x[s:s + n_fft] * window
        mag = np.abs(np.fft.rfft(frame))
        frames.append(mag)
    if not frames:
        return {"spec_hash": "", "spec_profile": {}}
    S = np.stack(frames, axis=0)
    S = np.log1p(S)
    freqs = np.fft.rfftfreq(n_fft, d=1.0 / sr)
    b1 = S[:, freqs < 200].mean() if np.any(freqs < 200) else 0.0
    b2 = S[:, (freqs >= 200) & (freqs < 2000)].mean() if np.any((freqs >= 200) & (freqs < 2000)) else 0.0
    b3 = S[:, freqs >= 2000].mean() if np.any(freqs >= 2000) else 0.0
    # temporal coarse profile
    t_profile = np.mean(S, axis=1)
    k = 16
    if len(t_profile) < k:
        t_bins = np.pad(t_profile, (0, k - len(t_profile)), mode="edge")[:k]
    else:
        idx = np.linspace(0, len(t_profile) - 1, k).astype(int)
        t_bins = t_profile[idx]
    vec = np.concatenate([
        np.array([float(b1), float(b2), float(b3)], dtype=np.float32),
        t_bins.astype(np.float32)
    ])
    # stable short hash
    import hashlib
    h = hashlib.sha1(np.round(vec, 4).tobytes()).hexdigest()[:16]
    return {
        "spec_hash": h,
        "spec_profile": {
            "low_band": float(b1),
            "mid_band": float(b2),
            "high_band": float(b3),
            "temporal_bins": [float(v) for v in t_bins.tolist()],
        },
    }


def _guess_genre(feat: dict) -> tuple[str, float]:
    tempo = float(feat.get("tempo_bpm", 0.0) or 0.0)
    centroid = float(feat.get("centroid_hz", 0.0) or 0.0)
    low_ratio = float(feat.get("low_ratio", 0.0) or 0.0)
    energy = float(feat.get("rms", 0.0) or 0.0)
    zcr = float(feat.get("zcr", 0.0) or 0.0)

    scores = {
        "electronic": 0.0,
        "hip-hop": 0.0,
        "rock": 0.0,
        "acoustic/ambient": 0.0,
    }
    if tempo >= 118:
        scores["electronic"] += 0.35
    if low_ratio >= 0.28:
        scores["hip-hop"] += 0.35
    if energy >= 0.07 and zcr >= 0.09:
        scores["rock"] += 0.35
    if energy < 0.045 and centroid < 2200:
        scores["acoustic/ambient"] += 0.45
    if centroid > 2800:
        scores["electronic"] += 0.15
        scores["rock"] += 0.1
    if low_ratio > 0.22 and tempo < 115:
        scores["hip-hop"] += 0.2
    if tempo < 95 and energy < 0.05:
        scores["acoustic/ambient"] += 0.2

    genre = max(scores, key=scores.get)
    conf = float(max(scores.values()))
    if conf < 0.25:
        return "unknown", conf
    return genre, min(conf, 0.95)


def _transcribe_music_preview(input_path: str) -> str:
    # Lightweight preview transcription to reduce hallucinations about lyrics.
    if "whisper_model" not in globals():
        return ""
    clip_path = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
    try:
        subprocess.run(
            ["ffmpeg", "-y", "-i", input_path, "-t", "35", "-ac", "1", "-ar", "16000", clip_path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL
        )
        result = whisper_model.transcribe(clip_path, task="transcribe", fp16=False)
        text = (result.get("text") or "").strip()
        return text[:400]
    except Exception:
        return ""
    finally:
        try:
            os.remove(clip_path)
        except Exception:
            pass


def _music_feature_summary(audio_bytes: bytes, filename: str) -> dict:
    ext = Path(filename or "").suffix.lower() or ".bin"
    in_path = tempfile.NamedTemporaryFile(suffix=ext, delete=False).name
    wav_path = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
    try:
        with open(in_path, "wb") as f:
            f.write(audio_bytes)

        base = _safe_audio_probe(in_path)

        subprocess.run(
            ["ffmpeg", "-y", "-i", in_path, "-ac", "1", "-ar", "16000", wav_path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL
        )
        with wave.open(wav_path, "rb") as wf:
            sr = wf.getframerate()
            nframes = wf.getnframes()
            nch = wf.getnchannels()
            pcm = wf.readframes(nframes)
        sig = np.frombuffer(pcm, dtype=np.int16).astype(np.float32)
        if sig.size == 0:
            return base
        x = sig / 32768.0
        rms = float(np.sqrt(np.mean(np.square(x))))
        spec = _spectral_features(x, sr)
        sig = _spectrogram_signature(x, sr)
        tempo = _estimate_tempo(x, sr)
        zc = float(spec.get("zcr", 0.0) or 0.0)

        if rms < 0.03:
            energy = "low"
        elif rms < 0.08:
            energy = "medium"
        else:
            energy = "high"

        if energy == "high" and zc > 0.12:
            mood = "hyped"
        elif energy == "low":
            mood = "calm"
        else:
            mood = "balanced"

        genre, genre_conf = _guess_genre({
            "tempo_bpm": tempo,
            "centroid_hz": spec.get("centroid_hz", 0.0),
            "low_ratio": spec.get("low_ratio", 0.0),
            "rms": rms,
            "zcr": zc,
        })

        tags = base.get("tags", {}) if isinstance(base.get("tags", {}), dict) else {}
        meta_title = tags.get("title") or tags.get("TITLE") or ""
        meta_artist = tags.get("artist") or tags.get("ARTIST") or ""
        meta_genre = tags.get("genre") or tags.get("GENRE") or ""
        lyrics_preview = _transcribe_music_preview(in_path)

        base.update({
            "duration_sec": float(base.get("duration_sec") or (len(x) / float(sr or 1))),
            "sample_rate": int(base.get("sample_rate") or sr),
            "channels": int(base.get("channels") or nch),
            "rms": rms,
            "zcr": zc,
            "tempo_bpm": tempo,
            "centroid_hz": float(spec.get("centroid_hz", 0.0) or 0.0),
            "rolloff_hz": float(spec.get("rolloff_hz", 0.0) or 0.0),
            "low_ratio": float(spec.get("low_ratio", 0.0) or 0.0),
            "energy": energy,
            "mood": mood,
            "genre_guess": genre,
            "genre_confidence": genre_conf,
            "meta_title": meta_title,
            "meta_artist": meta_artist,
            "meta_genre": meta_genre,
            "lyrics_preview": lyrics_preview,
            "spec_hash": sig.get("spec_hash", ""),
            "spec_profile": sig.get("spec_profile", {}),
        })
        return base
    except Exception:
        return {}
    finally:
        try:
            os.remove(in_path)
        except Exception:
            pass
        try:
            os.remove(wav_path)
        except Exception:
            pass


def _apply_music_impact(uid: int, features: dict) -> dict:
    """
    Let listened music influence internal emotional state (bot + user-state mirror).
    This makes "listening" affect subsequent responses.
    """
    try:
        e_label = (features.get("energy") or "medium").strip().lower()
        m_label = (features.get("mood") or "balanced").strip().lower()
        centroid = float(features.get("centroid_hz", 0.0) or 0.0)
        low_ratio = float(features.get("low_ratio", 0.0) or 0.0)

        e = 0.25
        if e_label == "high":
            e = 0.85
        elif e_label == "low":
            e = 0.10

        mood_warm = 0.0
        mood_tense = 0.0
        if "calm" in m_label:
            mood_warm += 0.12
            mood_tense -= 0.10
        elif "hyped" in m_label:
            mood_tense += 0.12
            mood_warm += 0.03
        else:
            mood_warm += 0.03

        spectral_spark = max(0.0, min(1.0, (centroid - 1200.0) / 2400.0))
        bass_ground = max(0.0, min(1.0, low_ratio))

        # Bot emotional shift
        bot_emotion.warmth = clamp(getattr(bot_emotion, "warmth", 0.0) + mood_warm + 0.05 * bass_ground)
        bot_emotion.tension = clamp(getattr(bot_emotion, "tension", 0.0) + mood_tense + 0.10 * e - 0.06 * bass_ground)
        bot_emotion.curiosity = clamp(getattr(bot_emotion, "curiosity", 0.0) + 0.08 * spectral_spark + 0.05 * e)
        bot_emotion.fatigue = clamp(getattr(bot_emotion, "fatigue", 0.0) - 0.10 * e)
        bot_emotion.sync = clamp(getattr(bot_emotion, "sync", 0.0) + 0.07 * bass_ground + 0.04 * (1.0 - abs(mood_tense)))

        # Mirror into user emotion-state (light touch)
        s = get_emotion_state(uid)
        s.warmth = clamp(s.warmth + 0.05 * mood_warm + 0.03 * bass_ground)
        s.tension = clamp(s.tension + 0.06 * mood_tense + 0.04 * e)
        s.curiosity = clamp(s.curiosity + 0.05 * spectral_spark)
        save_emotion_state(uid, s)

        return {
            "energy_drive": round(e, 3),
            "spark": round(spectral_spark, 3),
            "ground": round(bass_ground, 3),
            "bot_warmth": round(float(getattr(bot_emotion, "warmth", 0.0)), 3),
            "bot_tension": round(float(getattr(bot_emotion, "tension", 0.0)), 3),
            "bot_curiosity": round(float(getattr(bot_emotion, "curiosity", 0.0)), 3),
            "bot_sync": round(float(getattr(bot_emotion, "sync", 0.0)), 3),
        }
    except Exception:
        return {}


def _analyze_video_note_payload(video_bytes: bytes) -> dict:
    v_path = tempfile.NamedTemporaryFile(suffix=".mp4", delete=False).name
    wav_path = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
    frame_path = tempfile.NamedTemporaryFile(suffix=".jpg", delete=False).name
    try:
        with open(v_path, "wb") as f:
            f.write(video_bytes)

        meta = _safe_audio_probe(v_path)

        # Extract audio for speech analysis.
        subprocess.run(
            ["ffmpeg", "-y", "-i", v_path, "-ac", "1", "-ar", "16000", wav_path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL
        )

        transcript = ""
        try:
            if "whisper_model" in globals():
                stt = whisper_model.transcribe(
                    wav_path,
                    task="transcribe",
                    fp16=False
                )
                transcript = (stt.get("text") or "").strip()
        except Exception:
            transcript = ""

        # Extract representative frame.
        subprocess.run(
            ["ffmpeg", "-y", "-i", v_path, "-vf", "select=eq(n\\,5)", "-vframes", "1", frame_path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL
        )

        frame_bytes = b""
        try:
            with open(frame_path, "rb") as f:
                frame_bytes = f.read()
        except Exception:
            frame_bytes = b""

        return {
            "duration_sec": float(meta.get("duration_sec", 0.0) or 0.0),
            "transcript": transcript,
            "frame_bytes": frame_bytes,
        }
    except Exception:
        return {"duration_sec": 0.0, "transcript": "", "frame_bytes": b""}
    finally:
        for p in (v_path, wav_path, frame_path):
            try:
                os.remove(p)
            except Exception:
                pass


# ===== YOUTUBE VIDEO ANALYSIS (yt-dlp + youtube-transcript-api, NO official API) =====
# Когда пользователь присылает ссылку на YouTube, зефир скачивает видео локально
# (без API-ключей), достаёт субтитры/транскрипцию, кадры и заносит анализ в память.

YOUTUBE_URL_RE = re.compile(
    r"(?i)(?:https?://)?(?:www\.|m\.|music\.|gaming\.)?"
    r"(?:youtube\.com/(?:watch\?(?:.*&)?v=|shorts/|live/|embed/|v/)|youtu\.be/)"
    r"([\w-]{6,})"
)

# Не скачиваем полное видео для кадров, если оно длиннее этого (сек).
YOUTUBE_MAX_DOWNLOAD_SEC = 1200
# Лимит транскрипции whisper для аудио без субтитров (сек).
YOUTUBE_MAX_TRANSCRIBE_SEC = 900


def is_youtube_url(url: str) -> bool:
    return bool(YOUTUBE_URL_RE.search(url or ""))


def _youtube_video_id(url: str) -> str | None:
    m = YOUTUBE_URL_RE.search(url or "")
    return m.group(1) if m else None


def _fmt_duration(sec: float) -> str:
    sec = int(float(sec or 0.0))
    h, m, s = sec // 3600, (sec % 3600) // 60, sec % 60
    return f"{h}:{m:02d}:{s:02d}" if h else f"{m}:{s:02d}"


def _youtube_transcript(video_id: str, max_chars: int = 40000) -> str:
    """Быстрые субтитры без скачивания видео (работает, если есть captions)."""
    try:
        from youtube_transcript_api import YouTubeTranscriptApi
    except Exception:
        return ""
    try:
        api = YouTubeTranscriptApi()
        tlist = api.list(video_id)
        transcript = None
        for codes in (
            ["ru", "en", "uk", "de", "fr", "es", "pt", "pl", "it", "tr", "ar", "zh-Hans"],
            [],
        ):
            try:
                transcript = tlist.find_transcript(codes)
                break
            except Exception:
                continue
        if transcript is None:
            try:
                transcript = next(iter(tlist))
            except Exception:
                return ""
        fetched = transcript.fetch()
        text = " ".join(s.text for s in fetched).strip()
        return text[:max_chars]
    except Exception:
        return ""


def _youtube_metadata(url: str) -> dict:
    """Метаданные видео через yt-dlp (extract_info без скачивания)."""
    try:
        import yt_dlp
    except Exception:
        return {}
    vid = _youtube_video_id(url)
    watch_url = f"https://www.youtube.com/watch?v={vid}" if vid else url
    opts = {
        "quiet": True,
        "no_warnings": True,
        "skip_download": True,
        "noplaylist": True,
        "socket_timeout": 25,
        "extract_flat": "in_playlist",
        "no_color": True,
    }
    try:
        with yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(watch_url, download=False)
        if not isinstance(info, dict):
            return {}
        entries = info.get("entries")
        if entries:
            info = entries[0] if isinstance(entries, list) and entries else info
        return {
            "id": info.get("id") or vid or "",
            "title": (info.get("title") or "").strip(),
            "uploader": (info.get("uploader") or info.get("channel") or "").strip(),
            "channel": (info.get("channel") or "").strip(),
            "duration_sec": float(info.get("duration") or 0.0),
            "view_count": int(info.get("view_count") or 0),
            "like_count": int(info.get("like_count") or 0),
            "upload_date": (info.get("upload_date") or "").strip(),
            "description": (info.get("description") or "").strip(),
            "thumbnail": (info.get("thumbnail") or "").strip(),
            "categories": [c for c in (info.get("categories") or []) if c][:6],
            "tags": [(t or "")[:60] for t in (info.get("tags") or [])[:8]],
        }
    except Exception:
        return {}


def _youtube_download_video(url: str, out_dir: Path) -> str | None:
    """Скачивает видео в низком разрешении (progressive mp4), чтобы вытащить кадры."""
    try:
        import yt_dlp
    except Exception:
        return None
    vid = _youtube_video_id(url)
    watch_url = f"https://www.youtube.com/watch?v={vid}" if vid else url
    opts = {
        "quiet": True,
        "no_warnings": True,
        "noplaylist": True,
        "socket_timeout": 25,
        "format": "best[height<=360]/best[height<=480]/worst[ext=mp4]/worst",
        "outtmpl": str(out_dir / "video.%(ext)s"),
        "merge_output_format": "mp4",
        "noprogress": True,
        "retries": 2,
    }
    try:
        with yt_dlp.YoutubeDL(opts) as ydl:
            ydl.download([watch_url])
        for p in sorted(out_dir.iterdir()):
            if p.suffix.lower() in (".mp4", ".webm", ".mkv", ".mov", ".m4v"):
                return str(p)
    except Exception:
        pass
    return None


def _youtube_extract_frames(video_path: str, duration_sec: float, max_frames: int = 4) -> list[bytes]:
    """Вытаскивает несколько репрезентативных кадров через ffmpeg."""
    frames = []
    if not video_path or not os.path.exists(video_path):
        return frames
    duration_sec = float(duration_sec or 0.0)
    if duration_sec <= 0:
        duration_sec = 300.0
    fracs = [0.08, 0.3, 0.55, 0.8][:max_frames]
    for frac in fracs:
        t = min(max(duration_sec * frac, 0.5), max(duration_sec - 0.5, 0.5))
        out = tempfile.NamedTemporaryFile(suffix=".jpg", delete=False).name
        try:
            subprocess.run(
                ["ffmpeg", "-y", "-ss", f"{t:.2f}", "-i", video_path,
                 "-frames:v", "1", "-q:v", "3", out],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=60,
            )
            with open(out, "rb") as f:
                frames.append(f.read())
        except Exception:
            pass
        finally:
            try:
                os.remove(out)
            except Exception:
                pass
    return frames


def _youtube_audio_transcribe(video_path: str, max_sec: int = YOUTUBE_MAX_TRANSCRIBE_SEC) -> str:
    """Транскрипция аудиодорожки через whisper (когда субтитров нет)."""
    try:
        if "whisper_model" not in globals():
            return ""
        wav_path = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
        try:
            subprocess.run(
                ["ffmpeg", "-y", "-i", video_path, "-t", str(max_sec),
                 "-ac", "1", "-ar", "16000", wav_path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=120,
            )
            if not os.path.exists(wav_path) or os.path.getsize(wav_path) == 0:
                return ""
            stt = whisper_model.transcribe(wav_path, task="transcribe", fp16=False)
            return (stt.get("text") or "").strip()
        finally:
            try:
                os.remove(wav_path)
            except Exception:
                pass
    except Exception:
        return ""


def _youtube_thumbnail_bytes(url: str) -> bytes:
    """Превью видео (используется как фоллбек-кадр)."""
    vid = _youtube_video_id(url)
    if not vid:
        return b""
    for c in (
        f"https://i.ytimg.com/vi/{vid}/maxresdefault.jpg",
        f"https://i.ytimg.com/vi/{vid}/hqdefault.jpg",
        f"https://i.ytimg.com/vi/{vid}/mqdefault.jpg",
    ):
        try:
            r = requests.get(c, timeout=15)
            if r.status_code == 200 and r.content:
                return r.content
        except Exception:
            continue
    return b""


def _analyze_youtube_video_sync(url: str) -> dict:
    """Синхронная часть: метаданные + субтитры/whisper + кадры. Бежит в executor."""
    pack = {
        "url": url,
        "ok": False,
        "error": "",
        "id": "",
        "title": "",
        "uploader": "",
        "channel": "",
        "duration_sec": 0.0,
        "view_count": 0,
        "upload_date": "",
        "description": "",
        "transcript": "",
        "transcript_source": "",
        "frames": [],
        "frame_notes": [],
        "thumbnail_bytes": b"",
    }
    tmp_dir = Path(tempfile.mkdtemp(prefix="yt_analyze_"))
    try:
        meta = _youtube_metadata(url)
        for k in ("id", "title", "uploader", "channel", "duration_sec",
                  "view_count", "upload_date", "description"):
            if meta.get(k) not in (None, ""):
                pack[k] = meta.get(k)
        vid = _youtube_video_id(url) or (pack.get("id") or "")
        if not vid:
            pack["error"] = "не удалось распознать id видео"
            return pack

        pack["thumbnail_bytes"] = _youtube_thumbnail_bytes(url)

        # 1) Быстрые субтитры (полное покрытие, без скачивания).
        tr = _youtube_transcript(vid)
        if tr:
            pack["transcript"] = tr
            pack["transcript_source"] = "subtitles"

        # 2) Если субтитров нет — качаем низкое разрешение для кадров + whisper.
        duration = float(pack.get("duration_sec") or 0.0)
        video_path = None
        if duration <= YOUTUBE_MAX_DOWNLOAD_SEC or YOUTUBE_MAX_DOWNLOAD_SEC <= 0:
            video_path = _youtube_download_video(url, tmp_dir)
        if video_path:
            pack["frames"] = _youtube_extract_frames(video_path, duration)
            if not pack["transcript"]:
                tr2 = _youtube_audio_transcribe(video_path)
                if tr2:
                    pack["transcript"] = tr2
                    pack["transcript_source"] = "whisper"
        if not pack["transcript"] and pack["description"]:
            pack["transcript_source"] = "description"

        pack["ok"] = bool(pack["title"] or pack["transcript"] or pack["frames"])
        if not pack["ok"]:
            pack["error"] = "видео недоступно или заблокировано для скачивания"
        return pack
    except Exception as e:
        pack["ok"] = False
        pack["error"] = str(e)[:300]
        return pack
    finally:
        shutil.rmtree(tmp_dir, ignore_errors=True)


async def analyze_youtube_video(url: str) -> dict:
    """Полный пайплайн: скачивание/субтитры в executor + vision-анализ кадров."""
    loop = asyncio.get_running_loop()
    pack = await loop.run_in_executor(None, lambda: _analyze_youtube_video_sync(url))
    if not pack.get("ok"):
        return pack
    frames = pack.get("frames") or []
    if not frames and pack.get("thumbnail_bytes"):
        frames = [pack["thumbnail_bytes"]]
    notes = []
    for i, fb in enumerate(frames[:4]):
        try:
            note = await analyze_image_gemma3(
                fb,
                user_text=(
                    "Опиши, что происходит в этом кадре YouTube-видео: объекты, "
                    "обстановка, действия, люди, текст на экране, атмосфера. Одна короткая сводка."
                ),
            )
            notes.append(note or "")
        except Exception:
            notes.append("")
    pack["frame_notes"] = notes
    return pack


def _fallback_youtube_summary(pack: dict) -> str:
    title = pack.get("title") or "Без названия"
    ch = pack.get("uploader") or "-"
    d = _fmt_duration(pack.get("duration_sec"))
    tr = (pack.get("transcript") or "").strip()
    lines = [f"«{title}» — канал {ch}, длительность {d}."]
    if tr:
        lines.append("Содержание: " + tr[:800])
    return "\n".join(lines)


async def _handle_youtube_video_links(update, context, uid, urls, user_text):
    """Разбор YouTube-ссылки, ответ и запись анализа в память."""
    msg = update.effective_message
    url = urls[0]
    try:
        await update.message.reply_text("🎬 Watching YouTube-video…")
    except Exception:
        pass

    pack = await analyze_youtube_video(url)
    if not pack or not pack.get("ok"):
        detail = (pack or {}).get("error") or "unknown error"
        try:
            await update.message.reply_text(
                f"⚠️ Could not analyze YouTube video: {detail}"
            )
        except Exception:
            pass
        try:
            add_to_memory(uid, "user", f"[YOUTUBE FAIL] {url} | {detail}")
        except Exception:
            pass
        return

    title = pack.get("title") or "Без названия"
    duration_sec = float(pack.get("duration_sec") or 0.0)
    transcript = pack.get("transcript") or ""
    notes = " ".join(n for n in (pack.get("frame_notes") or []) if n).strip()

    # Согласованный вывод через основной мозг (как в fast-path для video notes).
    raw_answer = ""
    try:
        messages = get_conversation_messages(uid, limit=16)
        messages.append({
            "role": "system",
            "content": (
                "Ты анализируешь YouTube-видео по метаданным, субтитрам/транскрипции и кадрам.\n"
                "Собери цельный вывод: о чём видео, главные тезисы, что видно на кадрах, "
                "настроение/стиль, что важно запомнить."
            ),
        })
        response = await query_ollama_harmony(
            messages,
            reasoning_effort="high",
            max_tokens=1300,
            temperature=0.55,
            text=(
                f"Title: {title}\n"
                f"Channel: {pack.get('uploader') or '-'} | views: {pack.get('view_count') or 0} "
                f"| date: {pack.get('upload_date') or '-'}\n"
                f"Duration: {_fmt_duration(duration_sec)}\n\n"
                f"Description:\n{(pack.get('description') or '-')[:1500]}\n\n"
                f"Transcript ({pack.get('transcript_source') or '-'}):\n"
                f"{(transcript or '-')[:8000]}\n\n"
                f"Frames:\n{notes or '-'}"
            ),
            user_id=uid,
            inferred_intent="fact",
            force_max_tokens=1600,
        )
        raw_answer = (response.get("content") or "").strip()
    except Exception:
        raw_answer = ""

    if not raw_answer:
        raw_answer = _fallback_youtube_summary(pack)

    answer = ""
    try:
        answer = await render_tool_experience_reply(
            uid=uid,
            tool_name="youtube_video_analysis",
            tool_output=raw_answer,
            user_prompt=(user_text or "")[:400],
            extra_context=(
                f"title={title}\n"
                f"duration={_fmt_duration(duration_sec)}\n"
                f"transcript_source={pack.get('transcript_source') or '-'}\n"
                f"frames_analyzed={len(pack.get('frame_notes') or [])}"
            ),
        )
    except Exception:
        answer = raw_answer[:1800]

    try:
        await update.message.reply_text(answer, parse_mode="Markdown")
    except telegram.error.BadRequest:
        try:
            await update.message.reply_text(answer)
        except Exception:
            pass

    # --- Запись в память (video_memory + url_memory + история) ---
    try:
        add_user_video_memory(
            uid,
            file_id=url,
            analysis=answer,
            transcript=transcript,
            duration_sec=duration_sec,
        )
    except Exception:
        pass
    try:
        add_to_memory(uid, "user", f"[YOUTUBE] {title} ({_fmt_duration(duration_sec)}) | {url}")
        add_to_memory(uid, "assistant", f"YouTube video analysis: {answer[:500]}")
    except Exception:
        pass
    try:
        save_url_pages_to_memory(uid, [{
            "url": url,
            "ok": True,
            "title": title,
            "summary": raw_answer,
            "raw": f"{title}\n\n{transcript or pack.get('description') or ''}",
            "source_mode": "youtube",
        }])
    except Exception:
        pass


MUSIC_TRIGGER_PREFIXES = [
    "сгенерируй музыку",
    "сделай музыку",
    "сделай трек",
    "сгенерируй трек",
    "сделай бит",
    "generate music",
    "make music",
    "make a track",
    "generate a track",
]


def extract_music_prompt(text: str) -> str | None:
    if not text:
        return None
    t = text.strip()
    low = t.lower()
    for p in MUSIC_TRIGGER_PREFIXES:
        if low.startswith(p):
            rest = t[len(p):].strip(" :,-")
            return rest
    if re.search(r"\b(музык|трек|бит|melody|beat|music)\b", low) and re.search(r"\b(сгенер|создай|make|generate)\b", low):
        return t
    return None


_LYRIC_SECTION_RE = re.compile(
    r"^\[(intro|verse(?:\s*\d+)?|pre[- ]?chorus|chorus(?:\s*\d+)?|bridge|outro|hook|refrain)\b[^\]]*\]\s*$",
    re.IGNORECASE,
)

_LYRIC_SECTION_INLINE_RE = re.compile(
    r"^\[(intro|verse(?:\s*\d+)?|pre[- ]?chorus|chorus(?:\s*\d+)?|bridge|outro|hook|refrain)\b[^\]]*\]\s*(.*)$",
    re.IGNORECASE,
)


def _split_music_prompt_and_lyrics(text: str) -> tuple[str, str]:
    """
    Split a /music request into a musical prompt/title and user-provided lyrics.
    If the message looks like a lyric sheet, preserve it and keep the prompt minimal.
    """
    raw = (text or "").strip()
    if not raw:
        return "", ""
    lines = [line.rstrip() for line in raw.splitlines()]
    nonempty = [line.strip() for line in lines if line.strip()]
    if not nonempty:
        return "", ""

    # Inline lyric sheets: one line can start with a section header and continue with text.
    inline_idx = next((i for i, line in enumerate(lines) if _LYRIC_SECTION_INLINE_RE.match(line.strip())), None)
    if inline_idx is not None:
        prompt_text = "\n".join(line for line in lines[:inline_idx] if line.strip()).strip()
        lyrics_text = "\n".join(lines[inline_idx:]).strip()
        if prompt_text:
            return prompt_text, lyrics_text
        return "", lyrics_text

    header_idx = next((i for i, line in enumerate(lines) if _LYRIC_SECTION_RE.match(line.strip())), None)
    if header_idx is not None:
        prompt_text = "\n".join(line for line in lines[:header_idx] if line.strip()).strip()
        lyrics_text = "\n".join(lines[header_idx:]).strip()
        if prompt_text:
            return prompt_text, lyrics_text
        if len(nonempty) >= 2 and len(nonempty[0].split()) <= 6 and not _LYRIC_SECTION_RE.match(nonempty[0]):
            return nonempty[0], "\n".join(lines[1:]).strip()
        return "", lyrics_text

    lyricish_lines = sum(
        1
        for line in nonempty
        if not re.search(r"\b(?:сделай|создай|generate|make|music|музык|трек|бит|song|track)\b", line.lower())
    )
    avg_len = sum(len(line) for line in nonempty) / max(1, len(nonempty))
    if len(nonempty) >= 6 and lyricish_lines / max(1, len(nonempty)) >= 0.7 and avg_len <= 120:
        if len(nonempty[0].split()) <= 6:
            return nonempty[0], "\n".join(nonempty[1:]).strip()
        return "", raw
    return raw, ""


def _looks_like_user_lyrics_block(text: str) -> bool:
    raw = (text or "").strip()
    if not raw:
        return False
    lines = [line.strip() for line in raw.splitlines() if line.strip()]
    if not lines:
        return False
    if any(_LYRIC_SECTION_RE.match(line) or _LYRIC_SECTION_INLINE_RE.match(line) for line in lines):
        return True
    short_noncommand = 0
    lyric_like = 0
    for line in lines:
        low = line.lower()
        if re.search(r"\b(?:сделай|создай|generate|make|music|музык|трек|бит|song|track)\b", low):
            continue
        short_noncommand += 1
        if len(line.split()) <= 12:
            lyric_like += 1
    if short_noncommand >= 4 and lyric_like / max(1, short_noncommand) >= 0.75:
        return True
    if len(lines) >= 6 and sum(1 for line in lines if len(line.split()) <= 8) >= 4:
        return True
    return False


def _music_params_from_prompt(prompt: str) -> dict:
    low = (prompt or "").lower()
    style = "ambient"
    bpm = 92
    scale = "minor"
    duration = 18.0

    if any(k in low for k in [
        "классик", "классич", "classical", "оркестр", "orchestr", "симфон", "symphon",
        "барокко", "baroque", "сонат", "sonat", "прелюд", "фортепиан", "piano",
        "скрип", "violin", "виолончел", "cello", "струнн", "камерн", "опер", "опера",
    ]):
        style, bpm = "classical", 84
        duration = 26.0
    if any(k in low for k in ["lofi", "лоуфай", "чил", "chill"]):
        style, bpm = "lofi", 78
    if any(k in low for k in ["hyperpop", "hyper pop", "hypopop"]):
        style, bpm = "hyperpop", 148
    if any(k in low for k in ["baile funk", "funk carioca", "favela funk", "baile", "br funk"]):
        style, bpm = "baile_funk", 130
    if any(k in low for k in ["breakcore", "break core", "amen", "ragga jungle", "digital hardcore"]):
        style, bpm = "breakcore", 174
    if any(k in low for k in ["drum and bass", "drum & bass", "dnb", "jungle", "halftime", "half time", "liquid dnb", "neuro dnb"]):
        style, bpm = "drum_and_bass", 174
    if any(k in low for k in ["dubstep", "brostep", "wobble", "heavy bass"]):
        style, bpm = "dubstep", 140
    if any(k in low for k in ["edm", "dance", "клуб", "дэнс"]):
        style, bpm = "edm", 126
    if style == "ambient" and any(k in low for k in ["hip", "хип", "хоп", "рэп", "rap", "trap", "трэп", "бит"]):
        style, bpm = "hiphop", 92
    if any(k in low for k in ["rock", "рок"]):
        style, bpm = "rockish", 112
    if any(k in low for k in ["post-punk", "post punk", "postpunk", "cold wave", "new wave"]):
        style, bpm = "post_punk", 132
    if any(k in low for k in ["synthwave", "retrowave", "outrun", "vaporwave"]):
        style, bpm = "synthwave", 98
    if any(k in low for k in ["hardstyle", "hard style", "psy trance", "psytrance", "trance"]):
        style, bpm = "hardstyle", 150
    if any(k in low for k in ["techno", "tekno", "acid techno", "rave"]):
        style, bpm = "techno", 132
    if any(k in low for k in ["future beats", "futurebeat", "future beat", "future bass"]):
        style, bpm = "future_beats", 132
    if any(k in low for k in ["future garage", "futuregarage", "garage", "2-step", "two step"]):
        style, bpm = "future_garage", 130
    if any(k in low for k in ["trance", "uplifting trance", "progressive trance", "psy trance", "psytrance"]):
        style, bpm = "trance", 138
    if any(k in low for k in ["phonk", "drift phonk", "memphis phonk", "cowbell"]):
        style, bpm = "phonk", 160
    if any(k in low for k in ["sound design", "саунд дизайн", "саунд-диз", "sfx", "foley", "cinematic fx", "атмосфера", "атмосферный дизайн"]):
        style, bpm = "sound_design", 88
        duration = 14.0
    if any(k in low for k in ["happy", "весел", "радост"]):
        scale = "major"
    if any(k in low for k in ["sad", "sadness", "груст", "печаль", "тоск", "меланх", "душевн", "плач"]):
        scale = "minor"
    if any(k in low for k in ["slow", "медлен", "calm", "спокой"]):
        bpm = max(62, bpm - 16)
    if any(k in low for k in ["fast", "быстр", "energetic", "энерг"]):
        bpm = min(150, bpm + 18)

    mood = "balanced"
    if any(k in low for k in ["sad", "sadness", "груст", "печаль", "тоск", "меланх", "lonely", "одиноч"]):
        mood = "melancholic"
        bpm = max(58, bpm - 12)
        duration = max(duration, 24.0)
    elif any(k in low for k in ["dream", "ambient", "атмосфер", "cinematic", "ноч", "night"]):
        mood = "spacious"
    elif any(k in low for k in ["love", "romance", "intimate", "soft", "нежн"]):
        mood = "intimate"

    m = re.search(r"(\d{2,3})\s*bpm", low)
    if m:
        bpm = max(55, min(180, int(m.group(1))))
    sec = re.search(r"(\d{1,3})\s*(sec|s|сек|seconds?)", low)
    if sec:
        duration = max(6.0, min(60.0, float(sec.group(1))))

    energy = 0.55
    if mood == "melancholic":
        energy = 0.34
    elif mood == "intimate":
        energy = 0.42
    elif mood == "spacious":
        energy = 0.48
    if bpm >= 125:
        energy = max(energy, 0.72)
    elif bpm <= 80:
        energy = min(energy, 0.44)

    return {
        "style": style,
        "bpm": bpm,
        "scale": scale,
        "duration_sec": duration,
        "mood": mood,
        "energy": round(max(0.0, min(1.0, energy)), 3),
    }


