from playwright.async_api import async_playwright

async def fetch_via_browser(url: str, timeout: int = 60000) -> str:
    async with async_playwright() as p:
        browser = await p.chromium.launch(
            headless=True,
            args=[
                "--no-sandbox",
                "--disable-blink-features=AutomationControlled"
            ]
        )

        context = await browser.new_context(
            user_agent="Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
            locale="en-US"
        )

        page = await context.new_page()

        await page.goto(
            url,
            wait_until="networkidle",
            timeout=timeout
        )

        await page.wait_for_timeout(2000)

        html = await page.content()

        await browser.close()

        return html

from bs4.element import Tag

def find_main(soup: BeautifulSoup) -> Tag:
    # --- GitHub README / issues / gists ---
    for sel in [
        ".markdown-body",
        "article.markdown-body",
        "div[data-testid='readme']",
        "div.Box-body",
        "div.repository-content",
        "main"
    ]:
        gh = soup.select_one(sel)
        if gh and len(gh.get_text(strip=True)) > 100:
            return gh

    # --- Articles / blogs ---
    for sel in [
        "article",
        "main",
        "div[itemprop='articleBody']",
        "div[class*='content']",
        "div[class*='post']"
    ]:
        el = soup.select_one(sel)
        if el and len(el.get_text(strip=True)) > 200:
            return el

    return soup.body or soup

def smart_summary(text: str, limit: int = 1500) -> str:
    paras = [p for p in text.split("\n") if len(p) > 80]
    out = "\n".join(paras[:5])
    return out[:limit]


def _clean_extracted_page_text(text: str) -> str:
    if not text:
        return ""
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    cleaned = []
    seen = set()
    for ln in lines:
        low = ln.lower()
        if len(ln) < 2:
            continue
        if low in seen:
            continue
        if any(k in low for k in [
            "accept all cookies",
            "cookie settings",
            "advertisement",
            "all rights reserved"
        ]):
            continue
        seen.add(low)
        cleaned.append(ln)
    return "\n".join(cleaned)

def fetch_and_parse_url(url: str) -> dict:
    """
    Fetch a URL and extract meaningful text.
    Designed to reduce hallucination: if we can't extract content, we return ok=False.
    Note: This runs in a thread executor in handle_message, so asyncio.run(...) is safe here.
    """
    session = requests.Session()

    headers = {
        "User-Agent": "Mozilla/5.0",
        "Accept-Language": "en-US,en;q=0.9,ru;q=0.8",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,text/plain;q=0.8,*/*;q=0.5",
    }

    resp = None
    used_browser = False
    MAX_DOWNLOAD_BYTES = 2_000_000  # hard cap to avoid huge pages

    def _decode_body(body: bytes, content_type: str) -> str:
        m = re.search(r"charset=([\w-]+)", (content_type or ""), flags=re.IGNORECASE)
        if m:
            enc = m.group(1).strip().strip("\"'")
            try:
                return body.decode(enc, errors="replace")
            except Exception:
                pass
        try:
            enc = getattr(resp, "encoding", None) or getattr(resp, "apparent_encoding", None)
            if enc:
                return body.decode(enc, errors="replace")
        except Exception:
            pass
        return body.decode("utf-8", errors="replace")

    def _http_fetch() -> tuple[str, str]:
        nonlocal resp
        resp = session.get(
            url,
            headers=headers,
            timeout=20,
            allow_redirects=True,
            stream=True
        )
        if resp.status_code in (403, 429):
            raise RuntimeError("Blocked")
        resp.raise_for_status()
        ctype = (resp.headers.get("Content-Type") or "").lower()
        buf = bytearray()
        for chunk in resp.iter_content(chunk_size=65536):
            if not chunk:
                continue
            buf.extend(chunk)
            if len(buf) >= MAX_DOWNLOAD_BYTES:
                break
        return _decode_body(bytes(buf), ctype), ctype

    # --- TRY HTTP, then FALLBACK → BROWSER MODE ---
    try:
        body_text, ctype = _http_fetch()
    except Exception:
        try:
            body_text = asyncio.run(fetch_via_browser(url))
            ctype = "text/html; source=browser"
            used_browser = True
        except Exception as e:
            return {
                "url": url,
                "ok": False,
                "raw": "",
                "summary": f"ERROR: browser fetch failed: {e}",
                "title": "",
            }

    def _final_url() -> str:
        out = url
        try:
            if resp is not None and getattr(resp, "url", None):
                out = str(resp.url)
        except Exception:
            pass
        return out

    try:
        ctype_low = (ctype or "").lower()

        # Plain text / JSON / XML: keep as text.
        if (
            ("text/plain" in ctype_low)
            or ("application/json" in ctype_low)
            or ("application/xml" in ctype_low)
            or ("text/xml" in ctype_low)
        ):
            clean = _clean_extracted_page_text(body_text)
            if len(clean) < 80:
                raise ValueError("Too little text")
            final_url = _final_url()
            return {
                "url": final_url,
                "ok": True,
                "raw": clean[:12000],
                "summary": smart_summary(clean),
                "title": final_url,
                "source_mode": "browser" if used_browser else "http",
            }

        def _extract_html(html: str) -> tuple[str, str]:
            soup = BeautifulSoup(html, "html.parser")
            title = (soup.title.get_text(" ", strip=True) if soup.title else "").strip()[:200]
            main = find_main(soup)

            for tag in main.find_all(True):
                if tag.name in {"script", "style", "nav", "footer", "header", "aside", "form"}:
                    tag.decompose()

            for a in main.find_all("a"):
                href = a.get("href")
                txt = a.get_text(" ", strip=True)
                if href and txt:
                    a.replace_with(f"{txt} ({href})")

            raw = main.get_text("\n")
            clean = _clean_extracted_page_text(raw)
            return title, clean

        # HTML extraction.
        title, clean = _extract_html(body_text)

        if len(clean) < 200 and not used_browser:
            # Many modern sites need JS; retry once via browser even if HTTP succeeded.
            try:
                body_text = asyncio.run(fetch_via_browser(url))
                used_browser = True
                title, clean = _extract_html(body_text)
            except Exception:
                pass

        if len(clean) < 200:
            soup = BeautifulSoup(body_text, "html.parser")
            fallback_text = soup.get_text("\n", strip=True)
            fallback_text = _clean_extracted_page_text(fallback_text)
            if len(fallback_text) > len(clean):
                clean = fallback_text

        if len(clean) < 80:
            raise ValueError("Junk page")

        final_url = _final_url()
        return {
            "url": final_url,
            "ok": True,
            "raw": clean[:12000],
            "summary": smart_summary(clean),
            "title": title or final_url,
            "source_mode": "browser" if used_browser else "http",
        }

    except Exception as e:
        return {
            "url": url,
            "ok": False,
            "raw": "",
            "summary": f"PARSE ERROR: {e}",
            "title": "",
        }

def duckduckgo_search(query: str, max_results: int = 10, lang: str = "ru-ru") -> str:
    url = "https://html.duckduckgo.com/html/"
    headers = {
        "User-Agent": "Mozilla/5.0 (X11; Linux x86_64)",
        "Accept-Language": lang.replace("-", ",")
    }

    results = []

    for page in range(0, 3):
        data = {"q": query, "kl": lang, "s": page * 30}

        resp = None
        for attempt in range(3):
            try:
                resp = requests.post(url, data=data, headers=headers, timeout=15)
            except Exception:
                time.sleep(2 * (attempt + 1))
                continue
            if resp.status_code in (202, 429, 403, 503):
                time.sleep(2 * (attempt + 1))
                continue
            break

        if resp is None:
            continue

        try:
            resp.raise_for_status()
        except Exception:
            continue

        try:
            soup = BeautifulSoup(resp.text, "html.parser")

            for card in soup.select("div.result"):
                title_el = card.select_one("a.result__a")
                snippet_el = card.select_one("a.result__snippet, div.result__snippet")

                if not title_el:
                    continue

                title = title_el.get_text(strip=True)
                snippet = snippet_el.get_text(strip=True) if snippet_el else ""
                link = title_el.get("href", "")

                if not link or not verify_url(link):
                    continue

                block = f"• {title}\n  {snippet}\n  {link}"

                if block not in results:
                    results.append(block)

                if len(results) >= max_results:
                    break

            if len(results) >= max_results:
                break

        except Exception:
            continue

    if results:
        return "\n".join(results)

    # fallback 1: ddgs (если установлен в этом интерпретаторе)
    try:
        from ddgs import DDGS
        with DDGS() as ddgs:
            raw = list(ddgs.text(query, max_results=max_results * 3))
        blocks = []
        for r in raw[:max_results]:
            link = (r.get("href") or "").strip()
            if not link or not verify_url(link):
                continue
            blocks.append(f"• {r.get('title', '')}\n  {r.get('body', '')}\n  {link}")
        if blocks:
            return "\n".join(blocks)
    except Exception:
        pass

    # fallback 2: lite-эндпоинт
    try:
        resp = requests.post(
            "https://lite.duckduckgo.com/lite/",
            data={"q": query, "kl": lang},
            headers=headers,
            timeout=15,
        )
        if resp.status_code == 200:
            soup = BeautifulSoup(resp.text, "html.parser")
            blocks = []
            for a in soup.select("a[href]"):
                link = (a.get("href") or "").strip()
                if not link.startswith(("http://", "https://")):
                    continue
                title = a.get_text(strip=True)
                if not title:
                    continue
                block = f"• {title}\n  {link}"
                if block not in blocks:
                    blocks.append(block)
                if len(blocks) >= max_results:
                    break
            if blocks:
                return "\n".join(blocks)
    except Exception:
        pass

    return "No fresh data"


# ====== AUTO WEB SEARCH (FACT GROUNDING) ======
# If user asks for current facts and no URL blocks are provided, fetch a lightweight web search dump
# and feed it to the model as system context. This reduces hallucinations for "who is president" etc.
AUTO_WEB_SEARCH_ENABLED = True
AUTO_WEB_SEARCH_TTL_SECONDS = 12 * 60  # cache same query for 12 minutes
AUTO_WEB_SEARCH_MIN_SECONDS_BETWEEN = 25  # per user rate limit
AUTO_WEB_SEARCH_MAX_QUERY_CHARS = 240
_AUTO_WEB_CACHE: dict[str, tuple[float, str]] = {}

PRETOOL_BRAIN_ENABLED = True
PRETOOL_BRAIN_TIMEOUT_SECONDS = 1.25
PRETOOL_BRAIN_CACHE_TTL_SECONDS = 10 * 60
PRETOOL_BRAIN_REFRESH_INTERVAL_SECONDS = 180


def _normalize_web_query(text: str) -> str:
    t = (text or "").strip().lower()
    t = re.sub(r"\s+", " ", t)
    return t[:AUTO_WEB_SEARCH_MAX_QUERY_CHARS]


def _looks_like_fact_question(text: str) -> bool:
    t = (text or "").strip().lower()
    if not t:
        return False
    if len(t) > 600:
        return False
    if "?" in t:
        return True
    if re.match(r"^(кто|что|когда|где|почему|зачем|сколько|какой|какая|какие)\b", t):
        return True
    if re.match(r"^(who|what|when|where|why|how)\b", t):
        return True
    if any(k in t for k in [
        "президент", "столица", "курс", "цена", "стоимость", "население",
        "дата", "сегодня", "сейчас", "latest", "today", "now",
        "ceo", "founder", "head of state"
    ]):
        return True
    return False


def _cached_web_search_dump(query: str) -> str | None:
    key = _normalize_web_query(query)
    hit = _AUTO_WEB_CACHE.get(key)
    if not hit:
        return None
    ts, dump = hit
    if (time.time() - float(ts)) > AUTO_WEB_SEARCH_TTL_SECONDS:
        return None
    return dump


def _store_web_search_dump(query: str, dump: str) -> None:
    key = _normalize_web_query(query)
    if not key:
        return
    _AUTO_WEB_CACHE[key] = (time.time(), (dump or ""))
    # soft bound
    if len(_AUTO_WEB_CACHE) > 160:
        # drop oldest
        items = sorted(_AUTO_WEB_CACHE.items(), key=lambda kv: kv[1][0])
        for k, _v in items[:40]:
            _AUTO_WEB_CACHE.pop(k, None)


def maybe_auto_web_search(user_id: int, text: str, *, urls_present: bool, forced: bool = False) -> str | None:
    """
    Returns a search dump (string) or None.
    forced=True bypasses heuristics but keeps rate-limits.
    """
    if not AUTO_WEB_SEARCH_ENABLED:
        return None
    if urls_present:
        return None
    q = (text or "").strip()
    if not q:
        return None
    if (not forced) and (not _looks_like_fact_question(q)):
        return None

    try:
        profile = get_user_profile(int(user_id))
    except Exception:
        profile = {}
    try:
        now_ts = time.time()
        last_ts = float((profile or {}).get("auto_web_last_ts", 0.0) or 0.0)
        if now_ts - last_ts < AUTO_WEB_SEARCH_MIN_SECONDS_BETWEEN:
            cached = _cached_web_search_dump(q)
            return cached
        if isinstance(profile, dict):
            profile["auto_web_last_ts"] = now_ts
            try:
                save_user_profile(int(user_id))
            except Exception:
                pass
    except Exception:
        pass

    cached = _cached_web_search_dump(q)
    if cached:
        return cached

    # choose language heuristically
    lang = "en-us" if re.search(r"\b(usa|u\.s\.|сша|united states)\b", q.lower()) else "ru-ru"
    dump = duckduckgo_search(q[:AUTO_WEB_SEARCH_MAX_QUERY_CHARS], max_results=8, lang=lang)
    if dump:
        _store_web_search_dump(q, dump)
    return dump or None


@dataclass
class PreToolSnapshot:
    user_id: int
    query_key: str
    created_at: float
    search_dump: str = ""
    url_context: str = ""
    weather_context: str = ""
    news_context: str = ""
    active_memory_context: str = ""
    temporal_context: str = ""
    source_flags: dict[str, Any] = field(default_factory=dict)

    def to_context_block(self) -> str:
        parts: list[str] = []
        if self.search_dump.strip():
            parts.append("[PRETOOL_WEB]\n" + self.search_dump.strip())
        if self.url_context.strip():
            parts.append("[PRETOOL_URL]\n" + self.url_context.strip())
        if self.weather_context.strip():
            parts.append("[PRETOOL_WEATHER]\n" + self.weather_context.strip())
        if self.news_context.strip():
            parts.append("[PRETOOL_NEWS]\n" + self.news_context.strip())
        if self.active_memory_context.strip():
            parts.append("[PRETOOL_ACTIVE_MEMORY]\n" + self.active_memory_context.strip())
        if self.temporal_context.strip():
            parts.append("[PRETOOL_TEMPORAL]\n" + self.temporal_context.strip())
        return "\n\n".join(parts).strip()


def _pick_curiosity_topic(recent_topics: list[str]) -> str | None:
    """Once-per-day autonomous topic selection: zephyr picks what it wants to learn."""
    try:
        import httpx as _httpx
        recent = ", ".join(recent_topics[-6:]) or "пока нет"
        prompt = (
            "Ты автономный ИИ со своей любознательностью. Выбери ОДНУ новую тему или факт, "
            "который тебе по-настоящему интересно изучить сегодня, чтобы стать умнее: "
            "наука, история, космос, технологии, психология, культура, биология — что угодно.\n"
            f"Уже изученные темы: {recent}.\n"
            "Верни ТОЛЬКО тему одной короткой фразой (3-6 слов), без пояснений и кавычек."
        )
        resp = _httpx.post(
            "http://localhost:11434/api/chat",
            json={
                "model": "gemma3:4b",
                "messages": [{"role": "user", "content": prompt}],
                "stream": False,
                "options": {"temperature": 0.9},
            },
            timeout=90,
        )
        if resp.status_code != 200:
            return None
        topic = (resp.json().get("message", {}).get("content") or "").strip()
        topic = " ".join(topic.replace("\n", " ").split())
        if not topic or len(topic) > 80:
            return None
        return topic
    except Exception:
        return None


class PreToolBrain:
    """
    Prepares external/contextual data before the main LLM call.
    """

    def __init__(self):
        self.cache: dict[tuple[int, str], PreToolSnapshot] = {}
        self.last_refresh_ts: float = 0.0

    def _cache_key(self, user_id: int, text: str) -> tuple[int, str]:
        return int(user_id), _normalize_web_query(text or "")

    def _get_cached(self, user_id: int, text: str) -> PreToolSnapshot | None:
        key = self._cache_key(user_id, text)
        snap = self.cache.get(key)
        if not snap:
            return None
        if (time.time() - snap.created_at) > PRETOOL_BRAIN_CACHE_TTL_SECONDS:
            self.cache.pop(key, None)
            return None
        return snap

    def _store(self, snap: PreToolSnapshot) -> None:
        self.cache[(snap.user_id, snap.query_key)] = snap
        if len(self.cache) > 240:
            items = sorted(self.cache.items(), key=lambda kv: kv[1].created_at)
            for k, _v in items[:40]:
                self.cache.pop(k, None)

    async def prepare_turn(
        self,
        user_id: int,
        text: str,
        *,
        urls_present: bool,
        route_tool: str | None = None,
        inferred_intent: str = "normal",
        allow_wait: float = PRETOOL_BRAIN_TIMEOUT_SECONDS,
        allow_search: bool = True,
    ) -> PreToolSnapshot:
        key = self._cache_key(user_id, text)
        if allow_search:
            cached = self._get_cached(user_id, text)
            if cached:
                return cached

        loop = asyncio.get_running_loop()
        query = (text or "").strip()
        flags: dict[str, Any] = {
            "route_tool": route_tool or "",
            "inferred_intent": inferred_intent,
            "urls_present": bool(urls_present),
        }

        active_memory_context = ""
        temporal_context = ""
        url_context = ""
        weather_context = ""
        news_context = ""
        search_dump = ""

        try:
            active_memory_context = get_active_memory_context(user_id, limit=4)
        except Exception:
            active_memory_context = ""
        try:
            temporal_context = get_temporal_projection_context(user_id)
        except Exception:
            temporal_context = ""

        if is_url_followup_question(query) and not urls_present:
            try:
                url_context = get_url_memory_context(user_id, limit=2)
            except Exception:
                url_context = ""

        # Fast-path: precompute only what this turn likely needs.
        need_weather = bool(route_tool == "weather" or _looks_like_fact_question(query) and "погода" in query.lower())
        need_news = bool(route_tool == "news" or "новост" in query.lower())
        need_search = bool(
            route_tool in {"search", "fact", "lookup", "web_search"}
            or _looks_like_fact_question(query)
            or (route_tool is None and len(query) >= 4)
        )

        tasks = []
        if allow_search:
            if need_weather:
                tasks.append(("weather", loop.run_in_executor(None, lambda: collect_weather_signals_multi(query))))
            if need_news:
                tasks.append(("news", loop.run_in_executor(None, lambda: cognitive_duckduckgo_search(random.choice([
                    f"{query} последние новости",
                    f"{query} альтернативный взгляд",
                    f"{query} что происходит на самом деле",
                    f"{query} different perspective",
                ])))))
            if need_search and not urls_present:
                if route_tool in {"search", "fact", "lookup"}:
                    tasks.append(("search", loop.run_in_executor(None, lambda: maybe_auto_web_search(user_id, query, urls_present=False, forced=False))))
                elif route_tool is None:
                    tasks.append(("search", loop.run_in_executor(None, lambda: maybe_auto_web_search(user_id, query, urls_present=False, forced=True))))
                else:
                    tasks.append(("search", loop.run_in_executor(None, lambda: duckduckgo_search(query[:240], max_results=8, lang="ru-ru"))))

        for name, task in tasks:
            try:
                result = await asyncio.wait_for(task, timeout=allow_wait)
            except Exception:
                result = None
            if name == "weather" and result:
                weather_context = str(result)
            elif name == "news" and result:
                news_context = str(result)
            elif name == "search" and result:
                search_dump = str(result)

        snap = PreToolSnapshot(
            user_id=int(user_id),
            query_key=key[1],
            created_at=time.time(),
            search_dump=search_dump,
            url_context=url_context,
            weather_context=weather_context,
            news_context=news_context,
            active_memory_context=active_memory_context,
            temporal_context=temporal_context,
            source_flags=flags,
        )
        if allow_search:
            self._store(snap)
        return snap

    async def refresh_active_users(self) -> None:
        if not PRETOOL_BRAIN_ENABLED:
            return
        try:
            users = list(conversation_memory.keys())
        except Exception:
            users = []
        for uid_str in users[:12]:
            try:
                uid = int(uid_str)
            except Exception:
                continue
            try:
                recent = conversation_memory.get(uid_str, [])[-1:]
                last_text = ""
                if recent:
                    last_text = (recent[-1].get("content") or "").strip()
                if not last_text:
                    continue
                route_tool = infer_contextual_tool(last_text)
                urls_present = bool(extract_urls(last_text))
                await self.prepare_turn(uid, last_text, urls_present=urls_present, route_tool=route_tool, allow_search=False)
            except Exception:
                continue

    async def loop(self) -> None:
        await asyncio.sleep(30)
        while PRETOOL_BRAIN_ENABLED:
            try:
                await self.refresh_active_users()
            except Exception:
                pass
            try:
                await self._maybe_daily_curiosity_search()
            except Exception:
                pass
            await asyncio.sleep(PRETOOL_BRAIN_REFRESH_INTERVAL_SECONDS)

    # --- AUTONOMOUS DAILY CURIOSITY (self-learning, once per day) ---
    @staticmethod
    def _load_curiosity_state() -> dict:
        try:
            st = load_json(CURIOSITY_STATE_FILE)
            return st if isinstance(st, dict) else {}
        except Exception:
            return {}

    @staticmethod
    def _save_curiosity_state(st: dict) -> None:
        try:
            save_json(CURIOSITY_STATE_FILE, st)
        except Exception:
            pass

    async def _maybe_daily_curiosity_search(self) -> None:
        st = self._load_curiosity_state()
        last_ts = float(st.get("last_run_ts", 0.0) or 0.0)
        if (time.time() - last_ts) < CURIOSITY_INTERVAL_SECONDS:
            return
        loop = asyncio.get_running_loop()
        topic = await loop.run_in_executor(None, _pick_curiosity_topic, list(st.get("recent_topics", [])))
        if not topic:
            return
        dump = await loop.run_in_executor(None, lambda: duckduckgo_search(topic[:240], max_results=6, lang="ru-ru"))
        if not dump or "No fresh data" in dump:
            return
        summary = f"Тема: {topic}\n{dump[:1800]}"
        try:
            update_kb({f"self_learned_{datetime.now():%Y-%m-%d}": summary})
        except Exception:
            pass
        try:
            add_to_conversation_history(0, "system", "[SELF_LEARNED] " + summary[:1200])
        except Exception:
            pass
        st["last_run_ts"] = time.time()
        st["last_topic"] = topic
        st["recent_topics"] = (list(st.get("recent_topics", []))[-6:] + [topic])
        self._save_curiosity_state(st)
        logging.info("[CURIOSITY] daily self-learning search done: %s", topic)


pretool_brain = PreToolBrain()


def _extract_visual_query(text: str) -> str:
    t = (text or "").strip()
    if not t:
        return ""
    t = re.sub(
        r"(?i)\b(покажи|покажи мне|скинь|найди|дай|принеси|find|show|send|search|image|picture|photo|картинк[ауеи]?|фото|изображени[ея])\b",
        " ",
        t
    )
    t = re.sub(r"\s+", " ", t).strip(" ,.-")
    return t[:160]


def infer_contextual_tool(text: str) -> str | None:
    """
    Context-based tool routing (not phrase-bound).
    Returns one of: internet_image, image_generate, music_generate, weather, news, web_search, or None.

    Сначала решает ToolRouter (семантика + объект + эвиденция). Он же умеет
    уверенно сказать «инструмент не нужен» — тогда keyword-эвристики ниже
    не срабатывают («температура процессора» больше не вызывает погоду).
    """
    # --- TOOL ROUTER first ---
    try:
        dec = tool_router.route(text)
        dec_tool = dec.get("tool")
        dec_conf = float(dec.get("confidence", 0.0) or 0.0)
        if dec_tool != "none" and dec_conf >= tool_router.threshold:
            return dec_tool
        if dec_tool == "none" and dec_conf >= tool_router.none_threshold:
            return None
    except Exception:
        pass

    t = (text or "").strip().lower()
    if not t:
        return None

    visual_nouns = bool(re.search(r"\b(фото|картинк|изображен|pic|photo|image|wallpaper|арт)\b", t))
    ask_verbs = bool(re.search(r"\b(покажи|скинь|найди|дай|send|show|find)\b", t))
    gen_verbs = bool(re.search(r"\b(сгенер|создай|нарисуй|generate|create|draw)\b", t))
    music_nouns = bool(re.search(r"\b(музык|трек|бит|melody|beat|music|soundtrack)\b", t))
    weather_words = bool(re.search(r"\b(погода|прогноз|температур|weather|forecast)\b", t))
    news_words = bool(re.search(r"\b(новост|сводка|что нового|latest|news|headline)\b", t))
    search_words = bool(re.search(
        r"\b("
        r"найди|поищи|look up|search|"
        r"кто такой|что такое|расскажи про|"
        r"кто президент|who is (the )?president|president of"
        r")\b",
        t
    ))

    if visual_nouns and ask_verbs and not gen_verbs:
        return "internet_image"
    if t.startswith("/img") or t.startswith("/image"):
        return "image_generate"
    if gen_verbs and visual_nouns:
        return "image_generate"
    if gen_verbs and music_nouns:
        return "music_generate"
    if weather_words:
        return "weather"
    if news_words:
        return "news"
    if search_words:
        return "web_search"
    return None


def search_images_duckduckgo(query: str, max_results: int = 4) -> list[dict]:
    out = []
    try:
        q = (query or "").strip()
        if not q:
            return out
        headers = {"User-Agent": "Mozilla/5.0", "Referer": "https://duckduckgo.com/"}
        page = requests.get("https://duckduckgo.com/", params={"q": q, "iax": "images", "ia": "images"}, headers=headers, timeout=12)
        m = re.search(r"vqd=['\"]([^'\"]+)['\"]", page.text)
        if not m:
            return out
        vqd = m.group(1)
        r = requests.get(
            "https://duckduckgo.com/i.js",
            params={"l": "us-en", "o": "json", "q": q, "vqd": vqd, "f": ",,,"},
            headers=headers,
            timeout=12
        )
        r.raise_for_status()
        data = r.json()
        for it in (data.get("results") or [])[:max_results]:
            url = (it.get("image") or "").strip()
            title = (it.get("title") or "").strip()
            if verify_url(url):
                out.append({"url": url, "title": title or q, "source": "duckduckgo"})
    except Exception:
        return out
    return out


def search_images_wikimedia(query: str, max_results: int = 4) -> list[dict]:
    out = []
    try:
        q = (query or "").strip()
        if not q:
            return out
        resp = requests.get(
            "https://commons.wikimedia.org/w/api.php",
            params={
                "action": "query",
                "format": "json",
                "generator": "search",
                "gsrsearch": q,
                "gsrlimit": max_results,
                "gsrnamespace": 6,
                "prop": "imageinfo",
                "iiprop": "url",
            },
            timeout=14,
            headers={"User-Agent": "Mozilla/5.0"}
        )
        resp.raise_for_status()
        data = resp.json()
        pages = (data.get("query", {}) or {}).get("pages", {}) or {}
        for _, p in pages.items():
            ii = p.get("imageinfo") or []
            if not ii:
                continue
            url = (ii[0].get("url") or "").strip()
            title = (p.get("title") or "").replace("File:", "").strip()
            if verify_url(url):
                out.append({"url": url, "title": title or q, "source": "wikimedia"})
    except Exception:
        return out
    return out


def search_internet_images(query: str, max_results: int = 4) -> list[dict]:
    res = search_images_duckduckgo(query, max_results=max_results)
    if res:
        return res
    return search_images_wikimedia(query, max_results=max_results)


def download_reference_image(url: str, max_side: int = 896) -> Image.Image | None:
    try:
        if not verify_url(url):
            return None
        r = requests.get(
            url,
            timeout=14,
            headers={"User-Agent": "Mozilla/5.0"},
            stream=False
        )
        r.raise_for_status()
        data = r.content
        if not data:
            return None
        img = Image.open(io.BytesIO(data)).convert("RGB")
        w, h = img.size
        if max(w, h) > max_side:
            scale = float(max_side) / float(max(w, h))
            img = img.resize((max(64, int(w * scale)), max(64, int(h * scale))), Image.LANCZOS)
        return img
    except Exception:
        return None


def _clean_weather_core(text: str) -> str:
    t = (text or "").lower().strip()
    if not t:
        return ""

    # убираем метео-слова, оставляя локацию/контекст
    t = re.sub(
        r"\b(погода|прогноз|температура|weather|forecast|temperature|сейчас|today|tomorrow|завтра|сегодня)\b",
        " ",
        t
    )
    t = re.sub(r"[^\w\s\-а-яё]", " ", t, flags=re.IGNORECASE)
    t = re.sub(r"\s+", " ", t).strip()
    # fallback: if cleaning removed too much context, restore original input (lightly normalized)
    if not t:
        return (text or "").strip().lower()
    return t


def build_weather_queries(user_text: str) -> list[str]:
    raw = (user_text or "").strip()
    low = raw.lower()
    core = _clean_weather_core(raw)
    # safety fallback: avoid empty core causing weak queries
    if not core:
        core = raw.strip().lower()

    is_en = bool(re.search(r"[a-z]", low)) and not bool(re.search(r"[а-яё]", low))
    lang = "en-us" if is_en else "ru-ru"

    if is_en:
        base = f"weather {core}".strip() if core else "weather today"
        queries = [
            f"{base} now temperature wind humidity precipitation",
            f"{base} hourly forecast",
            f"{base} 3 day forecast",
        ]
        if "tomorrow" in low:
            queries.append(f"{base} tomorrow weather")
        if "week" in low or "weekly" in low:
            queries.append(f"{base} weekly weather forecast")
    else:
        base = f"погода {core}".strip() if core else "погода сегодня"
        queries = [
            f"{base} сейчас температура ветер влажность осадки",
            f"{base} прогноз по часам",
            f"{base} прогноз на 3 дня",
        ]
        if "завтра" in low:
            queries.append(f"{base} завтра")
        if "недел" in low:
            queries.append(f"{base} прогноз на неделю")

    dedup = []
    seen = set()
    for q in queries:
        qq = q.strip()
        if qq and qq not in seen:
            seen.add(qq)
            dedup.append(qq)
    return dedup[:5]


def collect_weather_signals(user_text: str) -> str:
    queries = build_weather_queries(user_text)
    if not queries:
        return ""

    is_en = bool(re.search(r"[a-z]", (user_text or "").lower())) and not bool(re.search(r"[а-яё]", (user_text or "").lower()))
    lang = "en-us" if is_en else "ru-ru"

    blocks = []
    seen_lines = set()
    for q in queries:
        ddg = duckduckgo_search(q, max_results=6, lang=lang)
        lines = []
        for line in (ddg or "").splitlines():
            s = line.strip()
            if not s or s in seen_lines:
                continue
            seen_lines.add(s)
            lines.append(s)
        if lines:
            blocks.append(f"◈ {q}\n" + "\n".join(lines[:18]))

    return "\n\n".join(blocks)[:9000]


def _detect_weather_lang(user_text: str) -> str:
    low = (user_text or "").lower()
    is_en = bool(re.search(r"[a-z]", low)) and not bool(re.search(r"[а-яё]", low))
    return "en" if is_en else "ru"


def _extract_weather_location(user_text: str) -> str:
    low = (user_text or "").strip()
    if not low:
        return ""
    core = _clean_weather_core(low)
    # убираем служебные хвосты
    core = re.sub(r"\b(сегодня|завтра|неделя|week|today|tomorrow|now|часам|hourly)\b", " ", core, flags=re.IGNORECASE)
    # убираем предлоги/служебные слова, которые ломают геокодинг
    core = re.sub(r"(?i)^\s*(в|во|на|у|около|рядом с|in|at|near)\s+", "", core).strip()
    core = re.sub(r"(?i)\b(город|city)\b", " ", core)
    core = re.sub(r"\s+", " ", core).strip(" ,.-")
    return core


def _weather_code_to_text(code: int, lang: str = "ru") -> str:
    ru_map = {
        0: "ясно",
        1: "преимущественно ясно",
        2: "переменная облачность",
        3: "пасмурно",
        45: "туман",
        48: "изморозь и туман",
        51: "слабая морось",
        53: "морось",
        55: "сильная морось",
        61: "слабый дождь",
        63: "дождь",
        65: "сильный дождь",
        71: "слабый снег",
        73: "снег",
        75: "сильный снег",
        80: "ливни",
        81: "ливни умеренные",
        82: "ливни сильные",
        95: "гроза",
        96: "гроза с градом",
        99: "сильная гроза с градом",
    }
    en_map = {
        0: "clear sky",
        1: "mainly clear",
        2: "partly cloudy",
        3: "overcast",
        45: "fog",
        48: "depositing rime fog",
        51: "light drizzle",
        53: "drizzle",
        55: "dense drizzle",
        61: "slight rain",
        63: "rain",
        65: "heavy rain",
        71: "slight snow",
        73: "snow",
        75: "heavy snow",
        80: "rain showers",
        81: "moderate showers",
        82: "violent showers",
        95: "thunderstorm",
        96: "thunderstorm with hail",
        99: "severe thunderstorm with hail",
    }
    table = en_map if lang == "en" else ru_map
    return table.get(int(code), "unknown" if lang == "en" else "неизвестно")


def fetch_wttr_weather(user_text: str) -> str:
    lang = _detect_weather_lang(user_text)
    loc = _extract_weather_location(user_text)
    loc_path = quote(loc) if loc else ""
    url = f"https://wttr.in/{loc_path}?format=j1"
    try:
        r = requests.get(
            url,
            timeout=12,
            headers={
                "User-Agent": "Mozilla/5.0",
                "Accept": "application/json,text/plain,*/*",
                "Accept-Language": "en-US,en;q=0.9,ru;q=0.8",
            },
        )
        r.raise_for_status()
        data = r.json()

        current = (data.get("current_condition") or [{}])[0]
        area = (data.get("nearest_area") or [{}])[0]
        area_name = ""
        if isinstance(area, dict):
            names = area.get("areaName") or []
            if names and isinstance(names[0], dict):
                area_name = names[0].get("value", "")

        temp = current.get("temp_C")
        feels = current.get("FeelsLikeC")
        hum = current.get("humidity")
        wind = current.get("windspeedKmph")
        desc_list = current.get("weatherDesc") or []
        desc = ""
        if desc_list and isinstance(desc_list[0], dict):
            desc = desc_list[0].get("value", "")

        days = []
        for d in (data.get("weather") or [])[:3]:
            date = d.get("date", "")
            maxt = d.get("maxtempC", "")
            mint = d.get("mintempC", "")
            rain = d.get("hourly", [{}])[0].get("chanceofrain", "")
            days.append(f"{date}: {mint}..{maxt}C, rain {rain}%")

        header = area_name or loc or ("your region" if lang == "en" else "твой регион")
        block = [
            f"◈ WTTR ({header})",
            f"now: {temp}C, feels {feels}C, humidity {hum}%, wind {wind} km/h, {desc}",
        ]
        if days:
            block.append("3-day: " + " | ".join(days))
        return "\n".join(block)
    except Exception as e:
        import traceback
        logging.error(f"[WEATHER] fetch_wttr_weather failed: {e}")
        logging.debug(traceback.format_exc())
        return ""


def fetch_open_meteo_weather(user_text: str) -> str:
    lang = _detect_weather_lang(user_text)
    loc = _extract_weather_location(user_text)
    if not loc:
        return ""
    try:
        g_url = (
            "https://geocoding-api.open-meteo.com/v1/search"
            f"?name={quote_plus(loc)}&count=1&language={'en' if lang == 'en' else 'ru'}&format=json"
        )
        headers = {
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json,text/plain,*/*",
            "Accept-Language": "en-US,en;q=0.9,ru;q=0.8",
        }
        g = requests.get(g_url, timeout=12, headers=headers)
        g.raise_for_status()
        g_data = g.json()
        results = g_data.get("results") or []
        if not results:
            return ""
        top = results[0]
        lat = top.get("latitude")
        lon = top.get("longitude")
        if lat is None or lon is None:
            return ""
        city = top.get("name", loc)
        country = top.get("country", "")

        f_url = (
            "https://api.open-meteo.com/v1/forecast"
            f"?latitude={lat}&longitude={lon}"
            "&current=temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m,weather_code"
            "&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,weather_code,uv_index_max"
            "&forecast_days=3&timezone=auto"
        )
        f = requests.get(f_url, timeout=12, headers=headers)
        f.raise_for_status()
        data = f.json()
        cur = data.get("current", {})
        daily = data.get("daily", {})

        temp = cur.get("temperature_2m")
        hum = cur.get("relative_humidity_2m")
        precip = cur.get("precipitation")
        wind = cur.get("wind_speed_10m")
        code = cur.get("weather_code", -1)
        desc = _weather_code_to_text(code, lang=lang)

        times = daily.get("time", [])
        tmax = daily.get("temperature_2m_max", [])
        tmin = daily.get("temperature_2m_min", [])
        p_sum = daily.get("precipitation_sum", [])
        uv = daily.get("uv_index_max", [])
        w_codes = daily.get("weather_code", [])
        lines = []
        for i in range(min(3, len(times))):
            dc = _weather_code_to_text(w_codes[i], lang=lang) if i < len(w_codes) else ""
            lines.append(
                f"{times[i]}: {tmin[i]}..{tmax[i]}C, precip {p_sum[i]}mm, uv {uv[i]}, {dc}"
            )

        return (
            f"◈ OPEN-METEO ({city}, {country})\n"
            f"now: {temp}C, humidity {hum}%, precipitation {precip}mm, wind {wind} km/h, {desc}\n"
            f"3-day: {' | '.join(lines)}"
        )
    except Exception as e:
        import traceback
        logging.error(f"[WEATHER] fetch_open_meteo_weather failed: {e}")
        logging.debug(traceback.format_exc())
        return ""


def collect_weather_signals_multi(user_text: str) -> str:
    parts = []

    open_meteo = fetch_open_meteo_weather(user_text)
    if open_meteo:
        parts.append(open_meteo)

    wttr = fetch_wttr_weather(user_text)
    if wttr:
        parts.append(wttr)

    ddg = collect_weather_signals(user_text)
    if ddg and "No fresh data" not in ddg:
        parts.append("◈ DUCKDUCKGO\n" + ddg[:4000])

    return "\n\n".join(parts)[:12000]

# ---------- REDDIT SEARCH LAYER ----------
def reddit_search(query: str, max_results: int = 5) -> str:
    """
    HTML-поиск по Reddit (без API), с fallback на old.reddit.
    """
    base_urls = [
        "https://www.reddit.com/search/?q=",
        "https://old.reddit.com/search?q="
    ]
    headers = {
        "User-Agent": "Mozilla/5.0",
        "Accept-Language": "en-US,en;q=0.9"
    }

    for base in base_urls:
        try:
            url = base + requests.utils.quote(query)
            resp = requests.get(url, headers=headers, timeout=15)
            resp.raise_for_status()

            soup = BeautifulSoup(resp.text, "html.parser")
            posts = []

            # new reddit
            for div in soup.select("div[data-testid='post-container']")[:max_results]:
                title_el = div.select_one("h3")
                snippet_el = div.select_one("p")
                if title_el:
                    title = title_el.get_text(strip=True)
                    snippet = snippet_el.get_text(strip=True) if snippet_el else ""
                    posts.append(f"• {title}\n  {snippet}")

            # old reddit fallback
            if not posts:
                for thing in soup.select("div.search-result")[:max_results]:
                    title_el = thing.select_one("a.search-title")
                    snippet_el = thing.select_one("div.search-result-meta")
                    if title_el:
                        title = title_el.get_text(strip=True)
                        snippet = snippet_el.get_text(strip=True) if snippet_el else ""
                        posts.append(f"• {title}\n  {snippet}")

            if posts:
                return "\n".join(posts)

        except Exception:
            continue

    return "Нет данных с Reddit"

