def concat_wavs(wav_paths, out_path):
    audios = []
    sr = None

    for p in wav_paths:
        audio, sr_ = sf.read(p, dtype="float32")
        sr = sr or sr_
        audios.append(audio)

    merged = np.concatenate(audios, axis=0)
    sf.write(out_path, merged, sr)
