import tempfile
import subprocess

async def transcribe_voice(ogg_path: str) -> dict:
    wav_path = ogg_path.replace(".ogg", ".wav")
    subprocess.run([
        "ffmpeg", "-y",
        "-i", ogg_path,
        "-ar", "16000",
        "-ac", "1",
        wav_path
    ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    result = whisper_model.transcribe(
        wav_path,
        task="transcribe",
        fp16=torch.cuda.is_available() or torch.backends.mps.is_available()
    )

    return {
        "text": result["text"].strip(),
        "language": result.get("language", "unknown"),
        "confidence": float(result.get("avg_logprob", 0))
    }

# ===== XTTS TTS UTILITY =====
def synthesize_voice_xtts(
    text: str,
    language: str = "ru",
    speaker_embedding=None,
    gpt_cond_latent=None,
    speaker_wav: str | None = None
) -> str:
    """
    Возвращает путь к OGG-файлу с голосом
    """
    with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as f:
        wav_path = f.name

    voice = speaker_wav or pick_voice_clone()

    xtts.tts_to_file(
        text=text,
        file_path=wav_path,
        speaker_wav=voice,
        language=language
    )

    ogg_path = wav_path.replace(".wav", ".ogg")

    subprocess.run([
        "ffmpeg", "-y",
        "-i", wav_path,
        "-c:a", "libopus",
        "-b:a", "32k",
        ogg_path
    ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    return ogg_path
    
