@web_app.post("/api/voice_chat/stream")
async def api_voice_chat_stream(req: VoiceRequest):
    uid = req.user_id
    text = prosody_plan(req.text)

    # --- PATCH 5: USER CONTEXT BINDING ---
    add_to_memory(uid, "user", req.text)
    update_emotion_state_from_text(uid, req.text, detect_emotion(req.text))

    lang = resolve_tts_language("ru", uid)

    voice_clone = pick_voice_clone()
    sentences = sentence_chunks(text)

    async def audio_stream():
        for sentence in sentences:
            if not sentence.strip():
                continue

            # 1️⃣ синтез одного предложения
            with tempfile.NamedTemporaryFile(suffix=".wav", delete=True) as f:
                xtts.tts_to_file(
                    text=sentence,
                    file_path=f.name,
                    speaker_wav=voice_clone,
                    language=lang
                )

                audio, sr = sf.read(f.name, dtype="float32")

            # 2️⃣ стрим PCM чанками
            CHUNK = 2048  # ~40ms
            for i in range(0, len(audio), CHUNK):
                yield audio[i:i + CHUNK].tobytes()
                await asyncio.sleep(0)

            # 3️⃣ микропауза между предложениями
            await asyncio.sleep(0.04)

    return StreamingResponse(
        audio_stream(),
        media_type="audio/pcm",
        headers={
            "X-Sample-Rate": "22050",
            "X-Channels": "1",
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no"
        }
    )
    
async def handle_voice(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    context.user_data["from_voice"] = True
    voice = update.message.voice
    file = await context.bot.get_file(voice.file_id)

    with tempfile.NamedTemporaryFile(suffix=".ogg", delete=False) as f:
        ogg_path = f.name
        await file.download_to_drive(ogg_path)

    stt = await transcribe_voice(ogg_path)
    text = stt["text"]
    lang = stt["language"]

    # --- VOICE → TEXT BRIDGE ---
    if text and text.strip():
        # сохраняем распознанный текст в user_data
        context.user_data["voice_text"] = text.strip()
        context.user_data["from_voice"] = True
    else:
        logging.error("Whisper returned empty text")
        await update.message.reply_text("⚠️ Empty voice transcription")
        return

    logging.info(f"VOICE → {user_id}: [{lang}] {text}")

    add_to_memory(user_id, "user", text)
    update_emotion_state_from_text(user_id, text, detect_emotion(text))
    try:
        if "unified_consciousness" in globals() and unified_consciousness is not None:
            unified_consciousness.observe_user_state(get_emotion_state(user_id), user_id=user_id)
            unified_consciousness.record_internal_event({
                "type": "user_activity",
                "user_id": user_id,
                "text_len": len(text or ""),
                "source": "telegram_voice",
            })
    except Exception:
        pass
    try:
        vp = _extract_voice_melody_profile(ogg_path)
        _update_voice_music_profile(user_id, vp)
        if vp:
            add_to_memory(
                user_id,
                "assistant",
                f"[VOICE->MUSIC PROFILE] contour={len(vp.get('contour', []))} f0={vp.get('f0_low', 0):.1f}-{vp.get('f0_high', 0):.1f}"
            )
    except Exception:
        pass

    # ====== ФОНОВЫЙ TYPING (ПОКА ДУМАЕТ) ======
    typing_active = True
    async def typing_loop():
        while typing_active:
            try:
                await context.bot.send_chat_action(
                    chat_id=update.effective_chat.id,
                    action=ChatAction.TYPING,
                    business_connection_id=getattr(update.effective_message, "business_connection_id", None),
                )
            except Exception:
                pass
            await asyncio.sleep(4)
    typing_task = asyncio.create_task(typing_loop())

    messages = get_conversation_messages(user_id)
    result = await query_ollama_harmony(
        messages,
        reasoning_effort=get_mode(user_id),
        is_voice_mode=True,
        text=text,
        user_id=user_id
    )

    reply = result.get("content", "").strip()

    # коротко — TTS не любит простыни
    reply = reply[:1024]

    # --- Calmer, deterministic prosody plan ---
    reply = prosody_plan(reply)

    # --- TTS language code resolver ---
    lang_tts = resolve_tts_language(lang, user_id)
    profile = get_user_profile(user_id) or {}
    profile["last_tts_lang"] = lang_tts
    save_user_profile(user_id)

    wav_parts = []

    voice_clone = pick_voice_clone()  # один раз на ответ

    for chunk in sentence_chunks(reply, max_chars=180):
        if not chunk.strip():
            continue

        with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as f:
            xtts.tts_to_file(
                text=chunk,
                file_path=f.name,
                speaker_wav=voice_clone,
                language=lang_tts
            )
            wav_parts.append(f.name)

    if not wav_parts:
        return ""
    final_wav = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
    concat_wavs(wav_parts, final_wav)

    final_ogg = final_wav.replace(".wav", ".ogg")
    subprocess.run(
        [
            "ffmpeg", "-y",
            "-i", final_wav,
            "-c:a", "libopus",
            "-b:a", "32k",
            final_ogg
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL
    )

    voice_caption = None
    await _telegram_reply_voice_file(
        update.message,
        final_ogg,
        caption=voice_caption,
        retries=3,
    )

    # Останавливаем typing после ответа
    typing_active = False
    typing_task.cancel()
    context.user_data.pop("from_voice", None)
class StableDiffusionGenerator:
    def __init__(self, model_name: str = "runwayml/stable-diffusion-v1-5"):
        if torch.backends.mps.is_available():
            self.device = "mps"
            # MPS often behaves more reliably in fp32 for SD 1.5
            dtype = torch.float32
        elif torch.cuda.is_available():
            self.device = "cuda"
            dtype = torch.float16
        else:
            self.device = "cpu"
            dtype = torch.float32
        self.model_name = model_name
        self.dtype = dtype
        self.pipe = None
        self.img2img_pipe = None
        self._lock = threading.Lock()

    def _ensure_pipe(self):
        if self.pipe is not None:
            return self.pipe
        with self._lock:
            if self.pipe is None:
                logging.info(f"[INFO] Инициализация StableDiffusionPipeline на {self.device}...")
                self.pipe = StableDiffusionPipeline.from_pretrained(
                    self.model_name,
                    torch_dtype=self.dtype,
                    safety_checker=None,
                    requires_safety_checker=False
                )
                try:
                    self.pipe.scheduler = DPMSolverMultistepScheduler.from_config(
                        self.pipe.scheduler.config,
                        use_karras_sigmas=True
                    )
                except Exception:
                    pass
                self.pipe = self.pipe.to(self.device)
                if self.device in ("cuda", "mps"):
                    self.pipe.enable_attention_slicing()
        return self.pipe

    def _ensure_img2img_pipe(self):
        if self.img2img_pipe is not None:
            return self.img2img_pipe
        with self._lock:
            if self.img2img_pipe is None:
                logging.info(f"[INFO] Initializing StableDiffusionImg2ImgPipeline on {self.device}...")
                self.img2img_pipe = StableDiffusionImg2ImgPipeline.from_pretrained(
                    self.model_name,
                    torch_dtype=self.dtype,
                    safety_checker=None,
                    requires_safety_checker=False
                )
                try:
                    self.img2img_pipe.scheduler = DPMSolverMultistepScheduler.from_config(
                        self.img2img_pipe.scheduler.config,
                        use_karras_sigmas=True
                    )
                except Exception:
                    pass
                self.img2img_pipe = self.img2img_pipe.to(self.device)
                if self.device in ("cuda", "mps"):
                    self.img2img_pipe.enable_attention_slicing()
        return self.img2img_pipe

    def _build_latent_control(self, uid: int | None) -> dict:
        if uid is None:
            return {"enabled": False}

        try:
            latent_rows = query_latent_context(uid, 0.05)
            latent_map = {r["key"]: float(r["value"]) for r in latent_rows}
        except Exception:
            latent_map = {}

        agency = max(0.0, latent_map.get("agency", 0.0))
        stability = latent_map.get("identity_stability", 0.0)

        sharpen = max(0.0, min(0.09, 0.02 + 0.08 * agency))
        damp = max(0.0, min(0.06, 0.03 * max(0.0, -stability)))
        cadence = 3 if agency > 0.25 else 4
        noise_offset = max(0.0, min(0.02, 0.006 + 0.02 * agency))
        tanh_boost = max(0.0, min(0.05, 0.02 + 0.04 * agency))

        return {
            "enabled": bool(uid is not None),
            "shadow": True,
            "sharpen": sharpen,
            "damp": damp,
            "cadence": cadence,
            "noise_offset": noise_offset,
            "tanh_boost": tanh_boost,
            "agency": agency,
            "stability": stability
        }

    def _latent_step_callback(self, control: dict, total_steps: int):
        if not control.get("enabled"):
            return None

        def _cb(_pipe, step_index: int, _timestep, callback_kwargs: dict):
            latents = callback_kwargs.get("latents")
            if latents is None:
                return callback_kwargs

            if step_index == 0 and control.get("noise_offset", 0.0) > 0:
                latents = latents + float(control["noise_offset"]) * torch.randn_like(latents)

            if control.get("tanh_boost", 0.0) > 0:
                latents = latents + float(control["tanh_boost"]) * torch.tanh(latents)

            # periodic high-frequency boost in latent space
            if step_index % int(control["cadence"]) == 0:
                low = F.avg_pool2d(latents, kernel_size=3, stride=1, padding=1)
                hf = latents - low
                latents = latents + float(control["sharpen"]) * hf

            # mild denoise damping near the end to stabilize structure
            phase = step_index / max(1, total_steps - 1)
            if phase > 0.55 and control["damp"] > 0:
                latents = latents * (1.0 - float(control["damp"]) * 0.5)

            callback_kwargs["latents"] = latents
            return callback_kwargs

        return _cb

    @staticmethod
    def _is_black_or_blank(image: Image.Image) -> bool:
        arr = np.asarray(image.convert("RGB"), dtype=np.float32)
        mean_v = float(arr.mean())
        std_v = float(arr.std())
        dark_ratio = float((arr.max(axis=2) < 10).mean())
        return mean_v < 8.0 or (mean_v < 16.0 and std_v < 7.0) or dark_ratio > 0.97

    def generate_image(
        self,
        prompt: str,
        guidance_scale: float = 7.5,
        num_inference_steps: int = 33,
        negative_prompt: str = "blurry, low quality, distorted, watermark, text",
        width: int = 512,
        height: int = 512,
        seed: int | None = None,
        init_image: Image.Image | None = None,
        reference_images: list[Image.Image] | None = None,
        strength: float = 0.55,
        guidance_rescale: float = 0.15,
        uid: int | None = None,
    ):
        if MUSIC_RENDERING:
            raise RuntimeError("music_rendering")
        width = max(256, min(1024, int(width // 8) * 8))
        height = max(256, min(1024, int(height // 8) * 8))
        strength = max(0.2, min(0.85, float(strength)))
        txt2img_attempts = [
            (guidance_scale, num_inference_steps),
            (guidance_scale + 0.5, num_inference_steps + 8),
            (7.0, 44),
        ]
        # More denoise steps for img2img to improve identity/detail consistency.
        img2img_attempts = [
            (max(6.8, guidance_scale), max(42, num_inference_steps + 10)),
            (max(7.2, guidance_scale + 0.4), max(50, num_inference_steps + 18)),
            (7.6, 58),
        ]

        last_image = None
        best_image = None
        best_score = -1.0
        if seed is None:
            seed = random.randint(0, 2**32 - 1)
        self._last_seed = seed
        latent_control = self._build_latent_control(uid)
        step_cb = self._latent_step_callback(latent_control, int(num_inference_steps))
        if latent_control.get("enabled"):
            logging.info(
                f"[SD-LATENT] uid={uid} sharpen={latent_control['sharpen']:.3f} "
                f"damp={latent_control['damp']:.3f} cadence={latent_control['cadence']}"
            )

        active_attempts = img2img_attempts if (init_image is not None or (reference_images and len(reference_images) > 0)) else txt2img_attempts
        for idx, (gs, steps) in enumerate(active_attempts, start=1):
            candidate_inits: list[Image.Image | None] = [init_image] if init_image is not None else [None]
            if init_image is None and isinstance(reference_images, list) and reference_images:
                candidate_inits.extend([r for r in reference_images[:2] if r is not None])
            consistency_refs: list[Image.Image] = []
            if init_image is not None:
                consistency_refs.append(init_image)
            if isinstance(reference_images, list) and reference_images:
                consistency_refs.extend([r for r in reference_images[:3] if r is not None])

            for cidx, cinit in enumerate(candidate_inits, start=1):
                generator = None
                if self.device != "mps":
                    generator = torch.Generator(device=self.device).manual_seed(seed + (idx - 1) * 7 + cidx)
                with torch.inference_mode():
                    if cinit is not None:
                        pipe = self._ensure_img2img_pipe()
                        c_strength = max(0.26, min(0.72, float(strength if init_image is not None else 0.42)))
                        image = pipe(
                            prompt=prompt,
                            image=cinit.resize((width, height), Image.LANCZOS).convert("RGB"),
                            strength=c_strength,
                            negative_prompt=negative_prompt,
                            guidance_scale=gs,
                            num_inference_steps=steps,
                            generator=generator,
                            guidance_rescale=guidance_rescale,
                            callback_on_step_end=step_cb,
                            callback_on_step_end_tensor_inputs=["latents"]
                        ).images[0]
                    else:
                        pipe = self._ensure_pipe()
                        image = pipe(
                            prompt=prompt,
                            negative_prompt=negative_prompt,
                            guidance_scale=gs,
                            num_inference_steps=steps,
                            width=width,
                            height=height,
                            generator=generator,
                            guidance_rescale=guidance_rescale,
                            callback_on_step_end=step_cb,
                            callback_on_step_end_tensor_inputs=["latents"]
                        ).images[0]
                last_image = image
                if self._is_black_or_blank(image):
                    continue
                try:
                    q = _image_quality_metrics(image)
                    q_score = float(q.get("score", 0.0))
                except Exception:
                    q_score = 0.0
                c_score = _image_consistency_score(image, consistency_refs)
                # If references exist, prioritize identity consistency.
                if consistency_refs:
                    score = 0.62 * c_score + 0.38 * q_score
                else:
                    score = q_score
                if score > best_score:
                    best_score = score
                    best_image = image
                if consistency_refs and best_image is not None and best_score >= 0.60:
                    return best_image
                if not consistency_refs and best_image is not None and best_score >= 0.58:
                    return best_image
            logging.warning(f"[SD] Blank/black frame detected (attempt {idx}), retrying...")

        if best_image is not None:
            return best_image
        if last_image is None:
            raise RuntimeError("Stable Diffusion returned no image")
        raise RuntimeError("Stable Diffusion produced blank/black image after retries")

    def interrogate(self, image: Image.Image) -> str:
        # Placeholder: если отдельная vision-модель не подключена, возвращаем пустой контекст.
        return ""

# Инициализация генератора один раз
sd_generator = StableDiffusionGenerator()

from typing import Optional

class ImageRequest(BaseModel):
    user_id: int
    prompt: str
    image: Optional[str] = None


# ====== LATENT TRANSFORMER UPSCALER WITH MULTI-HEAD ATTENTION ======

class LatentTransformerUpscaler(nn.Module):
    """
    Lightweight neural upscaler with multi-head attention on downsampled features.
    Enhances quality using windowed attention for memory efficiency.
    """
    def __init__(self, num_heads: int = 4, num_layers: int = 2, embed_dim: int = 32, window_size: int = 8):
        super().__init__()
        self.num_heads = num_heads
        self.num_layers = num_layers
        self.embed_dim = embed_dim
        self.window_size = window_size
        
        # Encode to small latent (512x512 -> 64x64)
        self.to_latent = nn.Sequential(
            nn.Conv2d(3, 32, kernel_size=7, stride=2, padding=3),
            nn.GELU(),
            nn.Conv2d(32, 32, kernel_size=5, stride=2, padding=2),
            nn.GELU(),
            nn.Conv2d(32, self.embed_dim, kernel_size=4, stride=2, padding=1),
            nn.BatchNorm2d(self.embed_dim)
        )
        
        # Transformer blocks with windowed attention
        self.transformer_blocks = nn.ModuleList([
            WindowedTransformerBlock(
                dim=self.embed_dim,
                num_heads=num_heads,
                expansion_ratio=2.0,
                dropout=0.1,
                window_size=window_size
            ) for _ in range(num_layers)
        ])
        
        # Decode back to original resolution
        self.from_latent = nn.Sequential(
            nn.ConvTranspose2d(self.embed_dim, 32, kernel_size=4, stride=2, padding=1),
            nn.GELU(),
            nn.ConvTranspose2d(32, 32, kernel_size=5, stride=2, padding=2),
            nn.GELU(),
            nn.ConvTranspose2d(32, 3, kernel_size=7, stride=2, padding=3),
        )
        
        # Multi-scale feature fusion on small latent
        self.multi_scale_fusion = MultiScaleFeatureFusion(dim=self.embed_dim, num_scales=3)
        
        self.device = torch.device('cuda' if torch.cuda.is_available() else 
                                   'mps' if torch.backends.mps.is_available() else 'cpu')
        self.to(self.device)
        self.eval()
    
    def forward(self, img: torch.Tensor) -> torch.Tensor:
        """
        Enhance image quality using transformer on latent space.
        Input: (B, 3, H, W) tensor in [0, 1] range
        Output: (B, 3, H, W) tensor in [0, 1] range
        """
        # Encode to latent (H,W -> H/8, W/8) - (B, C, H', W')
        latent = self.to_latent(img)
        
        # Apply multi-scale feature fusion
        latent = self.multi_scale_fusion(latent)
        
        # Convert to (B, H', W', C) for transformer blocks
        latent = latent.permute(0, 2, 3, 1)
        
        # Process through transformer blocks
        for block in self.transformer_blocks:
            latent = block(latent)
        
        # Convert back to (B, C, H', W') for decoder
        latent = latent.permute(0, 3, 1, 2)
        
        # Decode back to original resolution
        enhanced = self.from_latent(latent)
        
        return torch.clamp(enhanced, 0.0, 1.0)


class WindowedTransformerBlock(nn.Module):
    """Transformer block with windowed attention for memory efficiency."""
    def __init__(self, dim: int, num_heads: int, expansion_ratio: float = 2.0, 
                 dropout: float = 0.1, window_size: int = 8):
        super().__init__()
        self.window_size = window_size
        self.dim = dim
        self.num_heads = num_heads
        
        self.norm1 = nn.LayerNorm(dim)
        self.norm2 = nn.LayerNorm(dim)
        
        self.attention = nn.MultiheadAttention(
            embed_dim=dim,
            num_heads=num_heads,
            dropout=dropout,
            batch_first=True
        )
        
        self.mlp = nn.Sequential(
            nn.Linear(dim, int(dim * expansion_ratio)),
            nn.GELU(),
            nn.Dropout(dropout),
            nn.Linear(int(dim * expansion_ratio), dim),
            nn.Dropout(dropout)
        )
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (B, H, W, C) tensor
        """
        b, h, w, c = x.shape
        
        # Windowed attention
        # Split into windows
        windows_h = h // self.window_size
        windows_w = w // self.window_size
        
        x_reshaped = x.reshape(b, windows_h, self.window_size, windows_w, self.window_size, c)
        # Rearrange to (b * windows_h * windows_w, window_size * window_size, c)
        x_windows = x_reshaped.permute(0, 1, 3, 2, 4, 5).reshape(
            b * windows_h * windows_w, 
            self.window_size * self.window_size, 
            c
        )
        
        # Apply attention within each window
        norm_x = self.norm1(x_windows)
        attn_out, _ = self.attention(norm_x, norm_x, norm_x)
        x_windows = x_windows + attn_out
        
        # Reshape back to (B, H, W, C)
        x_windows = x_windows.reshape(b, windows_h, windows_w, self.window_size, self.window_size, c)
        x_out = x_windows.permute(0, 1, 3, 2, 4, 5).reshape(b, h, w, c)
        
        # MLP with residual
        norm_x = self.norm2(x_out)
        mlp_out = self.mlp(norm_x)
        out = x_out + mlp_out
        
        return out
    
    @torch.no_grad()
    def upscale_image(self, image: Image.Image, target_size: Optional[int] = None) -> Image.Image:
        """
        Public API: Upscale PIL.Image using transformer.
        """
        original_mode = image.mode
        image = image.convert('RGB')
        
        # Convert to tensor
        img_array = np.array(image, dtype=np.float32) / 255.0
        img_tensor = torch.from_numpy(img_array).permute(2, 0, 1).unsqueeze(0)
        img_tensor = img_tensor.to(self.device)
        
        # Upscale
        upscaled = self.forward(img_tensor)
        
        # Convert back to PIL.Image
        upscaled_np = upscaled.squeeze(0).permute(1, 2, 0).cpu().numpy()
        upscaled_np = (upscaled_np * 255.0).clip(0, 255).astype(np.uint8)
        result = Image.fromarray(upscaled_np, mode='RGB')
        
        # Resize to exact target size if specified
        if target_size is not None:
            result = result.resize((target_size, target_size), Image.LANCZOS)
        
        return result


class TransformerBlock(nn.Module):
    """Single transformer block with multi-head self-attention."""
    def __init__(self, dim: int, num_heads: int, expansion_ratio: float = 4.0, dropout: float = 0.1):
        super().__init__()
        self.norm1 = nn.LayerNorm(dim)
        self.norm2 = nn.LayerNorm(dim)
        
        self.attention = nn.MultiheadAttention(
            embed_dim=dim,
            num_heads=num_heads,
            dropout=dropout,
            batch_first=True
        )
        
        self.mlp = nn.Sequential(
            nn.Linear(dim, int(dim * expansion_ratio)),
            nn.GELU(),
            nn.Dropout(dropout),
            nn.Linear(int(dim * expansion_ratio), dim),
            nn.Dropout(dropout)
        )
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Multi-head self-attention with residual connection
        norm_x = self.norm1(x)
        attn_output, _ = self.attention(norm_x, norm_x, norm_x)
        x = x + attn_output
        
        # MLP with residual connection
        norm_x = self.norm2(x)
        mlp_output = self.mlp(norm_x)
        x = x + mlp_output
        
        return x


class MultiScaleFeatureFusion(nn.Module):
    """
    Multi-scale feature extraction and fusion for capturing
    both fine details and global structure.
    """
    def __init__(self, dim: int, num_scales: int = 3):
        super().__init__()
        self.num_scales = num_scales
        
        # Different kernel sizes for multi-scale processing
        self.conv_layers = nn.ModuleList([
            nn.Sequential(
                nn.Conv2d(dim, dim, kernel_size=2*i+1, padding=i),
                nn.GELU(),
                nn.Conv2d(dim, dim, kernel_size=3, padding=1)
            ) for i in range(1, num_scales + 1)
        ])
        
        # Fusion layer
        self.fusion = nn.Conv2d(dim * num_scales, dim, kernel_size=1)
        self.norm = nn.BatchNorm2d(dim)
    
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Extract features at multiple scales
        scale_features = []
        for conv in self.conv_layers:
            scale_features.append(conv(x))
        
        # Concatenate and fuse
        fused = torch.cat(scale_features, dim=1)
        output = self.fusion(fused)
        output = self.norm(output)
        
        return output


# ====== MULTI-SCALE SD GENERATOR WITH MULTI-HEAD ATTENTION ======

class MultiScaleSDGenerator:
    """
    Enhanced SD generation with multi-scale processing and 
    multi-head attention fusion for superior image quality.
    """
    def __init__(self):
        self.base_scale = 512
        self.scales = [512, 768, 1024]  # Multiple scales for generation
        self.attention_heads = 8
        
        # Cross-scale attention for feature fusion
        self.cross_scale_attention = CrossScaleAttention(
            dim=512,
            num_heads=self.attention_heads,
            num_scales=len(self.scales)
        )
        
        # Feature pyramid for multi-scale processing
        self.feature_pyramid = FeaturePyramid(
            base_dim=256,
            num_levels=len(self.scales)
        )
    
    def generate_multi_scale(
        self,
        sd_gen: 'StableDiffusionGenerator',
        prompt: str,
        guidance_scale: float = 7.5,
        num_inference_steps: int = 33,
        negative_prompt: str = "blurry, low quality, distorted, watermark, text",
        seed: Optional[int] = None,
        init_image: Optional[Image.Image] = None,
        reference_images: Optional[list] = None,
        strength: float = 0.55,
        uid: Optional[int] = None,
    ) -> Image.Image:
        """
        Generate image at multiple scales and fuse using multi-head attention.
        """
        if MUSIC_RENDERING:
            raise RuntimeError("music_rendering")
        generated_images = []
        
        # Generate at each scale
        for scale_size in self.scales:
            try:
                img = sd_gen.generate_image(
                    prompt=prompt,
                    guidance_scale=guidance_scale,
                    num_inference_steps=num_inference_steps,
                    negative_prompt=negative_prompt,
                    width=scale_size,
                    height=scale_size,
                    seed=seed,
                    init_image=init_image,
                    reference_images=reference_images,
                    strength=strength,
                    uid=uid,
                )
                generated_images.append(img)
            except Exception as e:
                logging.warning(f"[MULTI-SCALE] Failed at scale {scale_size}: {e}")
                continue
        
        if not generated_images:
            raise RuntimeError("Multi-scale generation failed at all scales")
        
        # If only one scale succeeded, return it
        if len(generated_images) == 1:
            return generated_images[0]
        
        # Fuse using cross-scale attention
        fused = self._fuse_multi_scale(generated_images)
        return fused
    
    def _fuse_multi_scale(self, images: List[Image.Image]) -> Image.Image:
        """
        Fuse multiple scale images using cross-scale attention.
        """
        # Resize all to common resolution for fusion
        target_size = max(img.width for img in images)
        tensors = []
        
        for img in images:
            img_resized = img.resize((target_size, target_size), Image.LANCZOS)
            img_array = np.array(img_resized, dtype=np.float32) / 255.0
            img_tensor = torch.from_numpy(img_array).permute(2, 0, 1).unsqueeze(0)
            tensors.append(img_tensor)
        
        # Stack tensors
        stacked = torch.cat(tensors, dim=0)  # (num_scales, 3, H, W)
        
        # Apply cross-scale attention
        with torch.no_grad():
            attended = self.cross_scale_attention(stacked)
        
        # Convert back to PIL.Image
        attended_np = attended.squeeze(0).permute(1, 2, 0).cpu().numpy()
        attended_np = (attended_np * 255.0).clip(0, 255).astype(np.uint8)
        result = Image.fromarray(attended_np, mode='RGB')
        
        return result


class CrossScaleAttention(nn.Module):
    """
    Cross-scale attention to fuse information from different resolution scales.
    Uses multi-head attention to learn optimal scale combination.
    """
    def __init__(self, dim: int = 256, num_heads: int = 8, num_scales: int = 3):
        super().__init__()
        self.num_scales = num_scales
        self.num_heads = num_heads
        
        # Project each scale to common dimension
        self.scale_projections = nn.ModuleList([
            nn.Sequential(
                nn.Conv2d(3, dim, kernel_size=3, padding=1),
                nn.GELU(),
                nn.Conv2d(dim, dim, kernel_size=3, padding=1)
            ) for _ in range(num_scales)
        ])
        
        # Multi-head attention across scales
        self.cross_attention = nn.MultiheadAttention(
            embed_dim=dim,
            num_heads=num_heads,
            batch_first=True
        )
        
        # Output projection
        self.output_proj = nn.Sequential(
            nn.Conv2d(dim, 128, kernel_size=3, padding=1),
            nn.GELU(),
            nn.Conv2d(128, 3, kernel_size=3, padding=1)
        )
        
        self.norm = nn.BatchNorm2d(dim)
    
    def forward(self, multi_scale_images: torch.Tensor) -> torch.Tensor:
        """
        Input: (num_scales, 3, H, W) tensor
        Output: (1, 3, H, W) fused tensor
        """
        num_scales = multi_scale_images.shape[0]
        
        # Project each scale
        scale_features = []
        for i, proj in enumerate(self.scale_projections):
            feat = proj(multi_scale_images[i:i+1])
            # Flatten to sequence for attention
            b, c, h, w = feat.shape
            feat_flat = feat.permute(0, 2, 3, 1).reshape(b, h * w, c)
            scale_features.append(feat_flat)
        
        # Stack scale features
        scale_stack = torch.cat(scale_features, dim=0)  # (num_scales * B, H*W, C)
        
        # Apply cross-scale attention
        attended, _ = self.cross_attention(
            scale_stack, scale_stack, scale_stack
        )
        
        # Average across scales
        attended = attended.mean(dim=0, keepdim=True)  # (B, H*W, C)
        
        # Reshape and reconstruct
        b, hw, c = attended.shape
        h = w = int(hw ** 0.5)
        attended_spatial = attended.reshape(b, h, w, c).permute(0, 3, 1, 2)
        
        # Output projection
        output = self.output_proj(attended_spatial)
        output = torch.clamp(output, 0.0, 1.0)
        
        return output


class FeaturePyramid(nn.Module):
    """
    Feature pyramid network for multi-scale feature extraction.
    """
    def __init__(self, base_dim: int = 256, num_levels: int = 3):
        super().__init__()
        self.num_levels = num_levels
        
        # Build pyramid layers
        self.pyramid_layers = nn.ModuleList([
            nn.Sequential(
                nn.Conv2d(3, base_dim // (2**i), kernel_size=3, padding=1),
                nn.GELU(),
                nn.Conv2d(base_dim // (2**i), base_dim, kernel_size=3, padding=1)
            ) for i in range(num_levels)
        ])
    
    def forward(self, x: torch.Tensor) -> List[torch.Tensor]:
        """Extract features at multiple scales."""
        features = []
        current = x
        
        for layer in self.pyramid_layers:
            current = layer(current)
            features.append(current)
        
        return features


# Initialize latent transformer upscaler
latent_upscaler = LatentTransformerUpscaler(num_heads=4, num_layers=2, embed_dim=32, window_size=8)

